export const PYTHON_FILES = {
  "addressing.py": "\"\"\"\nIPv4 Addressing and Subnetting Engine for NetForge.\n\nProvides exact bitwise calculations for IPv4 addresses, subnet masks,\nprefix lengths, network/broadcast addresses, usable host ranges,\nRFC 3021 (/31 point-to-point) support, and edge-case validation.\n\"\"\"\n\nfrom typing import Dict, Any, Tuple, Optional\n\n\ndef ip_to_int(ip_str: str) -> int:\n    \"\"\"Convert a dotted-decimal IPv4 string to a 32-bit unsigned integer.\"\"\"\n    if not isinstance(ip_str, str):\n        raise ValueError(f\"Invalid IP address format: {ip_str} (must be a string)\")\n    parts = ip_str.strip().split(\".\")\n    if len(parts) != 4:\n        raise ValueError(f\"IPv4 address must contain exactly 4 octets: {ip_str}\")\n    val = 0\n    for part in parts:\n        if not part.isdigit():\n            raise ValueError(f\"Octet must be numeric: '{part}' in {ip_str}\")\n        if len(part) > 1 and part.startswith(\"0\"):\n            raise ValueError(f\"Leading zeros not permitted in octet: '{part}'\")\n        num = int(part)\n        if num < 0 or num > 255:\n            raise ValueError(f\"Octet out of range (0-255): {num} in {ip_str}\")\n        val = (val << 8) | num\n    return val\n\n\ndef int_to_ip(ip_int: int) -> str:\n    \"\"\"Convert a 32-bit unsigned integer to dotted-decimal IPv4 string.\"\"\"\n    ip_int = ip_int & 0xFFFFFFFF\n    return f\"{(ip_int >> 24) & 0xFF}.{(ip_int >> 16) & 0xFF}.{(ip_int >> 8) & 0xFF}.{ip_int & 0xFF}\"\n\n\ndef int_to_binary_str(val: int, bits: int = 32) -> str:\n    \"\"\"Format an integer as a dotted binary string for educational display.\"\"\"\n    raw = f\"{val & 0xFFFFFFFF:032b}\"\n    return \".\".join([raw[0:8], raw[8:16], raw[16:24], raw[24:32]])\n\n\ndef prefix_to_mask_int(prefix: int) -> int:\n    \"\"\"Convert prefix length (0-32) to 32-bit mask integer.\"\"\"\n    if not isinstance(prefix, int) or prefix < 0 or prefix > 32:\n        raise ValueError(f\"Prefix length must be an integer between 0 and 32: {prefix}\")\n    if prefix == 0:\n        return 0\n    return ((0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF)\n\n\ndef mask_int_to_prefix(mask_int: int) -> int:\n    \"\"\"\n    Validate that an integer represents a valid contiguous subnet mask\n    and return its prefix length (0-32).\n    \"\"\"\n    mask_int = mask_int & 0xFFFFFFFF\n    # Check if mask consists of 1s followed by 0s:\n    # (~mask_int + 1) must be a power of 2\n    inverted = (~mask_int) & 0xFFFFFFFF\n    if ((inverted + 1) & inverted) != 0:\n        raise ValueError(f\"Subnet mask is non-contiguous: {int_to_ip(mask_int)}\")\n    \n    # Count set bits\n    prefix = bin(mask_int).count(\"1\")\n    return prefix\n\n\ndef mask_str_to_prefix(mask_str: str) -> int:\n    \"\"\"Convert dotted-decimal or prefix string ('255.255.255.0' or '/24' or '24') to prefix length.\"\"\"\n    mask_str = str(mask_str).strip()\n    if mask_str.startswith(\"/\"):\n        mask_str = mask_str[1:]\n    if mask_str.isdigit():\n        return prefix_to_mask_int_prefix(int(mask_str))\n    mask_int = ip_to_int(mask_str)\n    return mask_int_to_prefix(mask_int)\n\n\ndef prefix_to_mask_int_prefix(prefix: int) -> int:\n    if prefix < 0 or prefix > 32:\n        raise ValueError(f\"Prefix length out of range (0-32): {prefix}\")\n    return prefix\n\n\ndef prefix_to_mask_str(prefix: int) -> str:\n    \"\"\"Convert prefix length (0-32) to dotted-decimal mask string.\"\"\"\n    return int_to_ip(prefix_to_mask_int(prefix))\n\n\ndef is_valid_ipv4(ip_str: str) -> bool:\n    \"\"\"Check if string is a valid IPv4 address.\"\"\"\n    try:\n        ip_to_int(ip_str)\n        return True\n    except Exception:\n        return False\n\n\ndef is_valid_subnet_mask(mask_str: str) -> bool:\n    \"\"\"Check if string is a valid dotted-decimal or prefix subnet mask.\"\"\"\n    try:\n        mask_str_to_prefix(mask_str)\n        return True\n    except Exception:\n        return False\n\n\ndef get_network_int(ip_int: int, mask_int: int) -> int:\n    \"\"\"Calculate network address as 32-bit int.\"\"\"\n    return (ip_int & mask_int) & 0xFFFFFFFF\n\n\ndef get_broadcast_int(ip_int: int, mask_int: int) -> int:\n    \"\"\"Calculate broadcast address as 32-bit int.\"\"\"\n    wildcard = (~mask_int) & 0xFFFFFFFF\n    return ((ip_int & mask_int) | wildcard) & 0xFFFFFFFF\n\n\ndef is_same_subnet(ip1_str: str, ip2_str: str, mask_str: str) -> bool:\n    \"\"\"Determine whether two IPv4 addresses belong to the same subnet.\"\"\"\n    ip1 = ip_to_int(ip1_str)\n    ip2 = ip_to_int(ip2_str)\n    prefix = mask_str_to_prefix(mask_str)\n    mask = prefix_to_mask_int(prefix)\n    return get_network_int(ip1, mask) == get_network_int(ip2, mask)\n\n\ndef calculate_subnet_info(ip_str: str, mask_or_prefix: str) -> Dict[str, Any]:\n    \"\"\"\n    Perform complete subnet analysis and return structured educational metrics.\n    Handles standard subnets (/0 to /30), RFC 3021 point-to-point (/31), and host routes (/32).\n    \"\"\"\n    ip_int = ip_to_int(ip_str)\n    prefix = mask_str_to_prefix(mask_or_prefix)\n    mask_int = prefix_to_mask_int(prefix)\n    mask_str = int_to_ip(mask_int)\n    wildcard_int = (~mask_int) & 0xFFFFFFFF\n    wildcard_str = int_to_ip(wildcard_int)\n\n    network_int = get_network_int(ip_int, mask_int)\n    network_str = int_to_ip(network_int)\n    broadcast_int = get_broadcast_int(ip_int, mask_int)\n    broadcast_str = int_to_ip(broadcast_int)\n\n    total_addresses = 2 ** (32 - prefix)\n    \n    if prefix == 32:\n        # /32 Single Host Route\n        usable_hosts = 1\n        first_usable_int = ip_int\n        last_usable_int = ip_int\n        first_usable_str = int_to_ip(first_usable_int)\n        last_usable_str = int_to_ip(last_usable_int)\n        is_usable_host = True\n        note = \"RFC 3021/host route: /32 represents a single host or loopback address.\"\n    elif prefix == 31:\n        # /31 RFC 3021 Point-to-Point Links\n        usable_hosts = 2\n        first_usable_int = network_int\n        last_usable_int = broadcast_int\n        first_usable_str = int_to_ip(first_usable_int)\n        last_usable_str = int_to_ip(last_usable_int)\n        is_usable_host = True\n        note = \"RFC 3021 point-to-point link: both addresses are usable for host interfaces.\"\n    else:\n        # Standard /0 through /30\n        usable_hosts = max(0, total_addresses - 2)\n        if usable_hosts > 0:\n            first_usable_int = network_int + 1\n            last_usable_int = broadcast_int - 1\n            first_usable_str = int_to_ip(first_usable_int)\n            last_usable_str = int_to_ip(last_usable_int)\n            is_usable_host = (first_usable_int <= ip_int <= last_usable_int)\n        else:\n            first_usable_str = None\n            last_usable_str = None\n            is_usable_host = False\n        note = \"Standard IPv4 network with reserved network and broadcast addresses.\"\n\n    # Address classification\n    first_octet = (ip_int >> 24) & 0xFF\n    if first_octet < 128:\n        ip_class = \"A\"\n        default_cidr = 8\n    elif first_octet < 192:\n        ip_class = \"B\"\n        default_cidr = 16\n    elif first_octet < 224:\n        ip_class = \"C\"\n        default_cidr = 24\n    elif first_octet < 240:\n        ip_class = \"D (Multicast)\"\n        default_cidr = None\n    else:\n        ip_class = \"E (Experimental)\"\n        default_cidr = None\n\n    # RFC 1918 Private Address Detection\n    is_private = (\n        (10 << 24) <= ip_int <= ((10 << 24) | 0x00FFFFFF) or\n        ((172 << 24) | (16 << 16)) <= ip_int <= ((172 << 24) | (31 << 16) | 0xFFFF) or\n        ((192 << 24) | (168 << 16)) <= ip_int <= ((192 << 24) | (168 << 16) | 0xFFFF)\n    )\n    is_loopback = (127 << 24) <= ip_int <= ((127 << 24) | 0x00FFFFFF)\n    is_link_local = ((169 << 24) | (254 << 16)) <= ip_int <= ((169 << 24) | (254 << 16) | 0xFFFF)\n\n    return {\n        \"ip\": ip_str,\n        \"prefix\": prefix,\n        \"cidr\": f\"/{prefix}\",\n        \"subnet_mask\": mask_str,\n        \"wildcard_mask\": wildcard_str,\n        \"network_address\": network_str,\n        \"broadcast_address\": broadcast_str,\n        \"first_usable\": first_usable_str,\n        \"last_usable\": last_usable_str,\n        \"total_addresses\": total_addresses,\n        \"usable_hosts\": usable_hosts,\n        \"is_usable_host\": is_usable_host,\n        \"is_network_address\": (ip_int == network_int and prefix < 31),\n        \"is_broadcast_address\": (ip_int == broadcast_int and prefix < 31),\n        \"ip_binary\": int_to_binary_str(ip_int),\n        \"mask_binary\": int_to_binary_str(mask_int),\n        \"network_binary\": int_to_binary_str(network_int),\n        \"broadcast_binary\": int_to_binary_str(broadcast_int),\n        \"ip_class\": ip_class,\n        \"default_cidr\": default_cidr,\n        \"is_private\": is_private,\n        \"is_loopback\": is_loopback,\n        \"is_link_local\": is_link_local,\n        \"note\": note,\n    }\n",
  "cli.py": "\"\"\"\nSimulated Command-Line Interface (CLI) Parser for NetForge.\n\nProvides a Cisco-like terminal environment with EXEC and configuration modes,\ninspecting and modifying live device state, ARP caches, routing tables, and interfaces.\n\"\"\"\n\nfrom typing import Dict, Any, List, Optional, Tuple\nfrom netforge.addressing import (\n    is_valid_ipv4, is_valid_subnet_mask, mask_str_to_prefix, prefix_to_mask_str,\n    calculate_subnet_info\n)\nfrom netforge.devices import Device, Host, Switch, Router, Hub, Interface\nfrom netforge.topology import Topology\nfrom netforge.engine import SimulationEngine\n\n\nclass DeviceCLI:\n    def __init__(self, topology: Topology, device_id: str):\n        self.topology = topology\n        self.device_id = device_id\n        self.mode = \"PRIV_EXEC\"  # \"USER_EXEC\", \"PRIV_EXEC\", \"CONFIG\", \"CONFIG_IF\"\n        self.current_interface: Optional[str] = None\n\n    @property\n    def device(self) -> Optional[Device]:\n        return self.topology.devices.get(self.device_id)\n\n    def get_prompt(self) -> str:\n        dev = self.device\n        if not dev:\n            return \"NetForge> \"\n        name = dev.name\n        if isinstance(dev, Host):\n            return f\"{name}> \"\n        # Switch / Router Cisco-style prompts\n        if self.mode == \"CONFIG\":\n            return f\"{name}(config)# \"\n        elif self.mode == \"CONFIG_IF\":\n            return f\"{name}(config-if)# \"\n        elif self.mode == \"PRIV_EXEC\":\n            return f\"{name}# \"\n        return f\"{name}> \"\n\n    def execute(self, command_line: str, engine: Optional[SimulationEngine] = None) -> Dict[str, Any]:\n        \"\"\"\n        Execute a CLI command string.\n        Returns a dictionary with output, prompt, mode, and any triggered simulation events.\n        \"\"\"\n        raw = command_line.strip()\n        if not raw:\n            return {\n                \"output\": \"\",\n                \"prompt\": self.get_prompt(),\n                \"mode\": self.mode,\n                \"events\": []\n            }\n\n        dev = self.device\n        if not dev:\n            return {\"output\": \"Error: Device not found.\", \"prompt\": \"NetForge> \", \"mode\": self.mode, \"events\": []}\n\n        tokens = raw.split()\n        cmd = tokens[0].lower()\n        args = tokens[1:]\n\n        output = \"\"\n        events = []\n\n        if cmd in (\"help\", \"?\"):\n            output = self._cmd_help()\n\n        elif cmd == \"clear\":\n            output = \"__CLEAR__\"\n\n        elif cmd in (\"exit\", \"quit\"):\n            output = self._cmd_exit()\n\n        elif cmd in (\"ping\",):\n            output, events = self._cmd_ping(args, engine)\n\n        elif cmd in (\"traceroute\", \"tracert\"):\n            output, events = self._cmd_traceroute(args, engine)\n\n        elif cmd == \"show\":\n            output = self._cmd_show(args)\n\n        elif cmd in (\"ipconfig\", \"ifconfig\"):\n            output = self._cmd_ipconfig()\n\n        elif cmd in (\"arp\",):\n            output = self._cmd_arp(args)\n\n        # Cisco Mode Navigation\n        elif cmd in (\"enable\", \"en\"):\n            self.mode = \"PRIV_EXEC\"\n            output = \"\"\n\n        elif cmd in (\"disable\",):\n            self.mode = \"USER_EXEC\"\n            output = \"\"\n\n        elif cmd in (\"configure\", \"conf\"):\n            if len(args) > 0 and args[0].lower() in (\"terminal\", \"t\"):\n                if isinstance(dev, Host):\n                    output = \"% Configuration mode not required for PC/Host. You can use 'ip address' or 'ip default-gateway' directly.\"\n                else:\n                    self.mode = \"CONFIG\"\n                    output = \"Enter configuration commands, one per line. End with CNTL/Z or 'exit'.\"\n            else:\n                output = \"% Incomplete command. Syntax: configure terminal\"\n\n        elif cmd in (\"hostname\", \"host\"):\n            output = self._cmd_hostname(args)\n\n        elif cmd in (\"interface\", \"int\"):\n            output = self._cmd_interface(args)\n\n        elif cmd == \"ip\":\n            output = self._cmd_ip(args)\n\n        elif cmd == \"no\":\n            output = self._cmd_no(args)\n\n        elif cmd == \"shutdown\":\n            output = self._cmd_shutdown(True)\n\n        elif cmd in (\"clear-arp\", \"clear-mac\"):\n            output = self._cmd_clear_tables(cmd)\n\n        else:\n            output = f\"% Unknown command or invalid syntax: '{raw}'. Type 'help' or '?' for available commands.\"\n\n        return {\n            \"output\": output,\n            \"prompt\": self.get_prompt(),\n            \"mode\": self.mode,\n            \"events\": [e.to_dict() for e in events]\n        }\n\n    def _cmd_help(self) -> str:\n        dev = self.device\n        lines = [\n            \"NetForge Interactive CLI Help\",\n            \"-----------------------------\",\n            \"General Commands:\",\n            \"  help / ?                     Show this help message\",\n            \"  clear                        Clear terminal screen\",\n            \"  ping <ip>                    Send ICMP Echo Requests to target IPv4\",\n            \"  traceroute <ip>              Trace route hops to destination\",\n            \"  exit                         Exit current configuration mode\",\n            \"\",\n            \"Inspection Commands:\",\n            \"  show ip                      Display IP configuration and default gateway\",\n            \"  show interfaces              Display interface status, MAC, and IP configuration\",\n            \"  show ip int brief            Summary of interface states and IPs\",\n            \"  show arp                     Display ARP resolution cache table\",\n        ]\n\n        if isinstance(dev, Switch):\n            lines.extend([\n                \"  show mac address-table       Display learned Layer 2 MAC forwarding table\",\n                \"  clear mac address-table      Flush MAC address table\",\n            ])\n\n        if isinstance(dev, Router):\n            lines.extend([\n                \"  show ip route                Display IPv4 routing table\",\n                \"\",\n                \"Router Configuration Commands (in config mode):\",\n                \"  configure terminal           Enter global configuration mode\",\n                \"  hostname <name>              Set router hostname\",\n                \"  interface <name>             Select interface to configure\",\n                \"  ip address <ip> <mask>       Assign IPv4 address and subnet mask to interface\",\n                \"  shutdown / no shutdown       Disable or enable the selected interface\",\n                \"  ip route <net> <mask> <gw>   Add static IPv4 route\",\n                \"  no ip route <net> <mask>     Remove static IPv4 route\",\n            ])\n\n        if isinstance(dev, Host):\n            lines.extend([\n                \"\",\n                \"Host Configuration Commands:\",\n                \"  ip address <ip> <mask>       Assign IPv4 address and mask to primary interface\",\n                \"  ip default-gateway <ip>      Configure default gateway IPv4 address\",\n                \"  clear arp                    Flush ARP cache table\",\n            ])\n\n        return \"\\n\".join(lines)\n\n    def _cmd_exit(self) -> str:\n        if self.mode == \"CONFIG_IF\":\n            self.mode = \"CONFIG\"\n            self.current_interface = None\n            return \"\"\n        elif self.mode == \"CONFIG\":\n            self.mode = \"PRIV_EXEC\"\n            return \"\"\n        elif self.mode == \"PRIV_EXEC\":\n            self.mode = \"USER_EXEC\"\n            return \"\"\n        return \"Connection closed.\"\n\n    def _cmd_ping(self, args: List[str], engine: Optional[SimulationEngine]) -> Tuple[str, List[Any]]:\n        if not args:\n            return \"% Incomplete command. Syntax: ping <IPv4 address>\", []\n        target_ip = args[0]\n        if not is_valid_ipv4(target_ip):\n            return f\"% Invalid IPv4 address: {target_ip}\", []\n\n        dev = self.device\n        if not isinstance(dev, Host) and not isinstance(dev, Router):\n            return \"% Ping can only be originated from Hosts (PCs, Servers) or Routers.\", []\n\n        if not engine:\n            engine = SimulationEngine(self.topology)\n\n        # Run ping simulation (4 probes)\n        events = []\n        host_id = dev.id\n        try:\n            if isinstance(dev, Host):\n                events = engine.ping(host_id, target_ip, count=4)\n            else:\n                # Ping from router interface\n                op_iface = dev.get_first_operational_interface()\n                if not op_iface or not op_iface.ip_address:\n                    return \"% No operational interface with IP configured on this router to originate ping.\", []\n                # Router pinging\n                for seq in range(1, 5):\n                    icmp = ICMPPacket(type=ICMP_ECHO_REQUEST, sequence=seq)\n                    ip_pkt = IPv4Packet(src_ip=op_iface.ip_address, dst_ip=target_ip, ttl=64, protocol=\"ICMP\", payload=icmp)\n                    engine._forward_router_ip_packet(dev, ip_pkt)\n                    engine.run_all(50)\n                events = engine.events\n        except Exception as e:\n            return f\"% Ping simulation error: {str(e)}\", []\n\n        # Count successful echo replies\n        success_events = [e for e in events if e.event_type == \"PING_SUCCESS\" or (e.event_type == \"ROUTER_LOCAL_ICMP_REPLY\" and e.device_id != dev.id)]\n        drop_events = [e for e in events if \"DROP\" in e.event_type or \"NO_ROUTE\" in e.event_type or \"UNREACHABLE\" in e.event_type]\n\n        success_count = min(4, len(success_events))\n        loss_pct = int(((4 - success_count) / 4) * 100)\n\n        lines = [\n            f\"Pinging {target_ip} with 32 bytes of data:\",\n        ]\n        if success_count > 0:\n            for i in range(success_count):\n                lines.append(f\"Reply from {target_ip}: bytes=32 time=1ms TTL=64\")\n        if success_count < 4:\n            for _ in range(4 - success_count):\n                if drop_events:\n                    lines.append(f\"Request timed out. ({drop_events[-1].summary})\")\n                else:\n                    lines.append(\"Request timed out.\")\n\n        lines.extend([\n            f\"\\nPing statistics for {target_ip}:\",\n            f\"    Packets: Sent = 4, Received = {success_count}, Lost = {4 - success_count} ({loss_pct}% loss)\"\n        ])\n        return \"\\n\".join(lines), events\n\n    def _cmd_traceroute(self, args: List[str], engine: Optional[SimulationEngine]) -> Tuple[str, List[Any]]:\n        if not args:\n            return \"% Incomplete command. Syntax: traceroute <IPv4 address>\", []\n        target_ip = args[0]\n        if not is_valid_ipv4(target_ip):\n            return f\"% Invalid IPv4 address: {target_ip}\", []\n\n        dev = self.device\n        if not isinstance(dev, Host):\n            return \"% Traceroute currently supported from end hosts.\", []\n\n        if not engine:\n            engine = SimulationEngine(self.topology)\n\n        iface = dev.get_first_operational_interface()\n        if not iface or not iface.ip_address:\n            return \"% Host has no operational interface with configured IP.\", []\n\n        lines = [\n            f\"Tracing route to {target_ip} over a maximum of 30 hops:\",\n            \"\"\n        ]\n        all_events = []\n        hop = 1\n        reached = False\n\n        while hop <= 15 and not reached:\n            icmp = ICMPPacket(type=ICMP_ECHO_REQUEST, sequence=hop)\n            ip_pkt = IPv4Packet(src_ip=iface.ip_address, dst_ip=target_ip, ttl=hop, protocol=\"ICMP\", payload=icmp)\n            engine._send_ip_packet_from_host(dev, iface, ip_pkt)\n            engine.run_all(40)\n            all_events.extend(engine.events)\n\n            # Check what responded\n            te_events = [e for e in engine.events if e.event_type == \"ROUTER_TTL_EXPIRED\" and e.step >= hop]\n            succ_events = [e for e in engine.events if e.event_type == \"PING_SUCCESS\"]\n\n            if succ_events:\n                lines.append(f\"  {hop}    1 ms    1 ms    1 ms  {target_ip}\")\n                reached = True\n            elif te_events:\n                r_dev = self.topology.devices.get(te_events[-1].device_id)\n                r_ip = r_dev.get_first_operational_interface().ip_address if r_dev else \"Router\"\n                lines.append(f\"  {hop}    1 ms    1 ms    1 ms  {r_ip} [{r_dev.name if r_dev else ''}]\")\n            else:\n                lines.append(f\"  {hop}     *       *       *     Request timed out.\")\n                # If no response on early hop, break after 3 misses\n                if hop > 3 and all(\"*\" in l for l in lines[-3:]):\n                    break\n\n            hop += 1\n\n        lines.append(\"\\nTrace complete.\")\n        return \"\\n\".join(lines), all_events\n\n    def _cmd_show(self, args: List[str]) -> str:\n        if not args:\n            return \"% Incomplete command. Syntax: show ip | interfaces | arp | mac address-table | ip route\"\n        sub = args[0].lower()\n\n        if sub == \"ip\":\n            if len(args) > 1 and args[1].lower() == \"route\":\n                return self._show_ip_route()\n            if len(args) > 2 and args[1].lower() == \"int\" and args[2].lower() == \"brief\":\n                return self._show_interfaces_brief()\n            return self._show_ip()\n\n        elif sub in (\"interfaces\", \"interface\", \"int\"):\n            return self._show_interfaces()\n\n        elif sub == \"arp\":\n            return self._show_arp()\n\n        elif sub in (\"mac\", \"mac-address-table\"):\n            return self._show_mac_table()\n\n        return f\"% Invalid show command: 'show {' '.join(args)}'\"\n\n    def _show_ip(self) -> str:\n        dev = self.device\n        lines = [f\"IPv4 Configuration for {dev.name} ({dev.device_type.upper()}):\", \"\"]\n        if isinstance(dev, Host):\n            lines.append(f\"Default Gateway: {dev.default_gateway or 'None (Not configured)'}\")\n        for if_name, iface in dev.interfaces.items():\n            status = \"UP\" if iface.admin_up else \"ADMIN_DOWN\"\n            link_stat = \"CONNECTED\" if iface.is_connected else \"DISCONNECTED\"\n            lines.append(f\"Interface {if_name} ({status}, {link_stat}):\")\n            lines.append(f\"  MAC Address : {iface.mac_address}\")\n            lines.append(f\"  IPv4 Address: {iface.ip_address or 'Unassigned'}\")\n            lines.append(f\"  Subnet Mask : {iface.subnet_mask or 'Unassigned'} (/{iface.get_prefix() or 'N/A'})\")\n            lines.append(f\"  Network     : {iface.get_network_address() or 'N/A'}\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n\n    def _show_interfaces(self) -> str:\n        dev = self.device\n        lines = []\n        for if_name, iface in dev.interfaces.items():\n            admin = \"up\" if iface.admin_up else \"administratively down\"\n            proto = \"up\" if iface.is_operational else \"down\"\n            lines.append(f\"{if_name} is {admin}, line protocol is {proto}\")\n            lines.append(f\"  Hardware is Ethernet, address is {iface.mac_address}\")\n            if iface.ip_address and iface.subnet_mask:\n                lines.append(f\"  Internet address is {iface.ip_address}/{iface.get_prefix()}\")\n            else:\n                lines.append(\"  Internet address is not set\")\n            lines.append(f\"  MTU {iface.mtu} bytes, BW {iface.speed_mbps}000 Kbit/sec\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n\n    def _show_interfaces_brief(self) -> str:\n        dev = self.device\n        header = f\"{'Interface':<18} {'IP-Address':<16} {'OK?':<5} {'Method':<8} {'Status':<22} {'Protocol'}\"\n        lines = [header, \"-\" * 75]\n        for if_name, iface in dev.interfaces.items():\n            status = \"up\" if iface.admin_up else \"administratively down\"\n            proto = \"up\" if iface.is_operational else \"down\"\n            ip = iface.ip_address or \"unassigned\"\n            lines.append(f\"{if_name:<18} {ip:<16} {'YES':<5} {'manual':<8} {status:<22} {proto}\")\n        return \"\\n\".join(lines)\n\n    def _show_arp(self) -> str:\n        dev = self.device\n        lines = [\n            f\"Protocol  Address          Age (min)  Hardware Addr   Type   Interface\",\n            \"-\" * 65\n        ]\n        if not dev.arp_cache:\n            lines.append(\"ARP table is empty.\")\n            return \"\\n\".join(lines)\n\n        for ip, entry in dev.arp_cache.items():\n            lines.append(f\"Internet  {ip:<16} {'-':<10} {entry['mac']:<15} {entry.get('type', 'DYNAMIC'):<6} ARPA\")\n        return \"\\n\".join(lines)\n\n    def _show_mac_table(self) -> str:\n        dev = self.device\n        if not isinstance(dev, Switch):\n            return \"% MAC address table is only maintained by Layer 2 Ethernet switches.\"\n        lines = [\n            f\"          Mac Address Table\",\n            f\"-------------------------------------------\",\n            f\"Vlan    Mac Address       Type        Ports\",\n            f\"----    -----------       --------    -----\",\n        ]\n        if not dev.mac_table:\n            lines.append(\"Table is empty (no MAC addresses learned yet).\")\n            return \"\\n\".join(lines)\n\n        for mac, entry in dev.mac_table.items():\n            lines.append(f\"1       {mac:<17} {entry.get('type', 'DYNAMIC'):<11} {entry['port']}\")\n        return \"\\n\".join(lines)\n\n    def _show_ip_route(self) -> str:\n        dev = self.device\n        if not isinstance(dev, Router):\n            return \"% Routing table is only maintained by Layer 3 Routers.\"\n        lines = [\n            \"Codes: C - connected, S - static, * - candidate default\",\n            \"\",\n            \"Gateway of last resort is not set\",\n            \"\"\n        ]\n        routes = dev.get_all_routes()\n        if not routes:\n            lines.append(\"Routing table is empty.\")\n            return \"\\n\".join(lines)\n\n        for r in routes:\n            code = \"C\" if r.route_type == \"C\" else (\"S*\" if r.is_default_route() else \"S\")\n            if r.route_type == \"C\":\n                lines.append(f\"{code:<3} {r.network}/{r.prefix} is directly connected, {r.interface_name}\")\n            else:\n                via = f\"via {r.next_hop}\" if r.next_hop else f\"is directly connected, {r.interface_name}\"\n                lines.append(f\"{code:<3} {r.network}/{r.prefix} [{r.metric}/0] {via}\")\n        return \"\\n\".join(lines)\n\n    def _cmd_ipconfig(self) -> str:\n        return self._show_ip()\n\n    def _cmd_arp(self, args: List[str]) -> str:\n        if args and args[0] in (\"-a\", \"-g\"):\n            return self._show_arp()\n        elif args and args[0] == \"-d\":\n            self.device.clear_arp_cache()\n            return \"ARP cache successfully cleared.\"\n        return self._show_arp()\n\n    def _cmd_hostname(self, args: List[str]) -> str:\n        if not args:\n            return \"% Incomplete command. Syntax: hostname <name>\"\n        self.device.name = args[0]\n        return \"\"\n\n    def _cmd_interface(self, args: List[str]) -> str:\n        if not args:\n            return \"% Incomplete command. Syntax: interface <interface_name>\"\n        iface_name = args[0]\n        # Match case-insensitively\n        target = None\n        for k in self.device.interfaces.keys():\n            if k.lower() == iface_name.lower():\n                target = k\n                break\n        if not target:\n            return f\"% Interface {iface_name} does not exist on this device.\"\n        self.current_interface = target\n        self.mode = \"CONFIG_IF\"\n        return \"\"\n\n    def _cmd_ip(self, args: List[str]) -> str:\n        if not args:\n            return \"% Incomplete command.\"\n        sub = args[0].lower()\n\n        if sub == \"address\":\n            # ip address <ip> <subnet_mask>\n            if len(args) < 3:\n                return \"% Incomplete command. Syntax: ip address <IPv4> <SubnetMask>\"\n            ip = args[1]\n            mask = args[2]\n            if not is_valid_ipv4(ip):\n                return f\"% Invalid IPv4 address: {ip}\"\n            if not is_valid_subnet_mask(mask):\n                return f\"% Invalid subnet mask: {mask}\"\n\n            # If inside interface mode:\n            if self.mode == \"CONFIG_IF\" and self.current_interface:\n                iface = self.device.get_interface(self.current_interface)\n                iface.ip_address = ip\n                iface.subnet_mask = prefix_to_mask_str(mask_str_to_prefix(mask))\n                return f\"Interface {self.current_interface} configured with IP {ip} {iface.subnet_mask}\"\n\n            # If host:\n            if isinstance(self.device, Host):\n                op_iface = self.device.get_first_operational_interface() or next(iter(self.device.interfaces.values()), None)\n                if op_iface:\n                    op_iface.ip_address = ip\n                    op_iface.subnet_mask = prefix_to_mask_str(mask_str_to_prefix(mask))\n                    return f\"Host {self.device.name} interface {op_iface.name} configured with IP {ip} {op_iface.subnet_mask}\"\n            return \"% Select an interface first using 'interface <name>'\"\n\n        elif sub == \"default-gateway\":\n            if len(args) < 2:\n                return \"% Incomplete command. Syntax: ip default-gateway <IPv4>\"\n            gw = args[1]\n            if not is_valid_ipv4(gw):\n                return f\"% Invalid gateway IPv4: {gw}\"\n            if isinstance(self.device, Host):\n                self.device.default_gateway = gw\n                return f\"Default gateway configured to {gw}\"\n            return \"% 'ip default-gateway' is used for Host devices. For routers, use 'ip route 0.0.0.0 0.0.0.0 <next-hop>'.\"\n\n        elif sub == \"route\":\n            # ip route <network> <mask> <next_hop>\n            if not isinstance(self.device, Router):\n                return \"% Static routes can only be configured on Routers.\"\n            if len(args) < 4:\n                return \"% Incomplete command. Syntax: ip route <network> <subnet_mask> <next_hop_ip>\"\n            net = args[1]\n            mask = args[2]\n            next_hop = args[3]\n            if not is_valid_ipv4(net):\n                return f\"% Invalid network IP: {net}\"\n            if not is_valid_subnet_mask(mask):\n                return f\"% Invalid subnet mask: {mask}\"\n            if not is_valid_ipv4(next_hop):\n                return f\"% Invalid next-hop IP: {next_hop}\"\n\n            mask_str = prefix_to_mask_str(mask_str_to_prefix(mask))\n            self.device.add_static_route(net, mask_str, next_hop=next_hop)\n            return f\"Static route to {net}/{mask_str} via {next_hop} added.\"\n\n        return f\"% Unknown ip command: 'ip {' '.join(args)}'\"\n\n    def _cmd_no(self, args: List[str]) -> str:\n        if not args:\n            return \"% Incomplete command.\"\n        sub = args[0].lower()\n\n        if sub == \"shutdown\":\n            return self._cmd_shutdown(False)\n\n        elif sub == \"ip\" and len(args) > 1 and args[1].lower() == \"route\":\n            # no ip route <network> <mask>\n            if len(args) < 4:\n                return \"% Incomplete command. Syntax: no ip route <network> <mask_or_prefix>\"\n            net = args[2]\n            mask = args[3]\n            mask_str = prefix_to_mask_str(mask_str_to_prefix(mask))\n            if isinstance(self.device, Router):\n                self.device.remove_static_route(net, mask_str)\n                return f\"Static route to {net} {mask_str} removed.\"\n            return \"% Device is not a router.\"\n\n        return f\"% Command not recognized: 'no {' '.join(args)}'\"\n\n    def _cmd_shutdown(self, shutdown: bool) -> str:\n        if self.mode != \"CONFIG_IF\" or not self.current_interface:\n            return \"% Enter interface configuration mode first ('interface <name>').\"\n        iface = self.device.get_interface(self.current_interface)\n        if not iface:\n            return \"% Interface not found.\"\n        iface.admin_up = not shutdown\n        state_str = \"administratively down\" if shutdown else \"up\"\n        return f\"Interface {iface.name} changed state to {state_str}\"\n\n    def _cmd_clear_tables(self, cmd: str) -> str:\n        if \"arp\" in cmd:\n            self.device.clear_arp_cache()\n            return \"ARP cache cleared.\"\n        elif \"mac\" in cmd and isinstance(self.device, Switch):\n            self.device.clear_mac_table()\n            return \"MAC address table cleared.\"\n        return \"\"\n",
  "devices.py": "\"\"\"\nDevice Models and Interfaces for NetForge.\n\nImplements PCs, Laptops, Servers, Ethernet Switches, Routers, and Hubs,\nwith interface state, MAC tables, ARP caches, and routing tables.\n\"\"\"\n\nfrom typing import Dict, List, Optional, Any, Tuple\nimport time\nfrom netforge.addressing import (\n    ip_to_int, int_to_ip, mask_str_to_prefix, prefix_to_mask_int,\n    get_network_int, is_same_subnet, prefix_to_mask_str\n)\nfrom netforge.protocols import (\n    BROADCAST_MAC, ZERO_MAC, EthernetFrame, ARPPacket, IPv4Packet, ICMPPacket,\n    ETHERTYPE_ARP, ETHERTYPE_IPV4, ARP_OP_REQUEST, ARP_OP_REPLY\n)\n\nTuple_Ports = Tuple[str, List[str]]\n\n\nclass Interface:\n    def __init__(\n        self,\n        name: str,\n        mac_address: str,\n        ip_address: Optional[str] = None,\n        subnet_mask: Optional[str] = None,\n        admin_up: bool = True,\n        link_id: Optional[str] = None,\n        mtu: int = 1500,\n        speed_mbps: int = 1000\n    ):\n        self.name = name\n        self.mac_address = mac_address.upper()\n        self.ip_address = ip_address\n        self.subnet_mask = subnet_mask\n        self.admin_up = admin_up\n        self.link_id = link_id\n        self.mtu = mtu\n        self.speed_mbps = speed_mbps\n\n    @property\n    def is_connected(self) -> bool:\n        return self.link_id is not None\n\n    @property\n    def is_operational(self) -> bool:\n        return self.admin_up and self.is_connected\n\n    def get_prefix(self) -> Optional[int]:\n        if not self.subnet_mask:\n            return None\n        return mask_str_to_prefix(self.subnet_mask)\n\n    def get_network_address(self) -> Optional[str]:\n        if not self.ip_address or not self.subnet_mask:\n            return None\n        ip_i = ip_to_int(self.ip_address)\n        prefix = self.get_prefix()\n        mask_i = prefix_to_mask_int(prefix)\n        return int_to_ip(get_network_int(ip_i, mask_i))\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"name\": self.name,\n            \"mac_address\": self.mac_address,\n            \"ip_address\": self.ip_address,\n            \"subnet_mask\": self.subnet_mask,\n            \"admin_up\": self.admin_up,\n            \"link_id\": self.link_id,\n            \"is_connected\": self.is_connected,\n            \"is_operational\": self.is_operational,\n            \"prefix\": self.get_prefix(),\n            \"network_address\": self.get_network_address(),\n            \"mtu\": self.mtu,\n            \"speed_mbps\": self.speed_mbps,\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Interface\":\n        return cls(\n            name=data[\"name\"],\n            mac_address=data[\"mac_address\"],\n            ip_address=data.get(\"ip_address\"),\n            subnet_mask=data.get(\"subnet_mask\"),\n            admin_up=data.get(\"admin_up\", True),\n            link_id=data.get(\"link_id\"),\n            mtu=data.get(\"mtu\", 1500),\n            speed_mbps=data.get(\"speed_mbps\", 1000),\n        )\n\n\nclass Route:\n    def __init__(\n        self,\n        network: str,\n        mask: str,\n        next_hop: Optional[str] = None,\n        interface_name: Optional[str] = None,\n        metric: int = 1,\n        route_type: str = \"S\"  # \"C\" for Connected, \"S\" for Static\n    ):\n        self.network = network\n        self.mask = mask\n        self.prefix = mask_str_to_prefix(mask)\n        self.network_int = ip_to_int(network)\n        self.mask_int = prefix_to_mask_int(self.prefix)\n        self.next_hop = next_hop\n        self.interface_name = interface_name\n        self.metric = metric\n        self.route_type = route_type\n\n    def matches(self, dest_ip_str: str) -> bool:\n        dest_int = ip_to_int(dest_ip_str)\n        return (dest_int & self.mask_int) == (self.network_int & self.mask_int)\n\n    def is_default_route(self) -> bool:\n        return self.network == \"0.0.0.0\" and self.prefix == 0\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"network\": self.network,\n            \"mask\": self.mask,\n            \"prefix\": self.prefix,\n            \"cidr\": f\"{self.network}/{self.prefix}\",\n            \"next_hop\": self.next_hop,\n            \"interface_name\": self.interface_name,\n            \"metric\": self.metric,\n            \"route_type\": self.route_type,\n            \"is_default\": self.is_default_route()\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Route\":\n        return cls(\n            network=data[\"network\"],\n            mask=data[\"mask\"],\n            next_hop=data.get(\"next_hop\"),\n            interface_name=data.get(\"interface_name\"),\n            metric=data.get(\"metric\", 1),\n            route_type=data.get(\"route_type\", \"S\")\n        )\n\n\nclass Device:\n    def __init__(\n        self,\n        id: str,\n        name: str,\n        device_type: str,\n        x: float = 0.0,\n        y: float = 0.0\n    ):\n        self.id = id\n        self.name = name\n        self.device_type = device_type\n        self.x = x\n        self.y = y\n        self.interfaces: Dict[str, Interface] = {}\n        # ARP cache: ip -> {\"mac\": str, \"timestamp\": float, \"type\": \"DYNAMIC\"}\n        self.arp_cache: Dict[str, Dict[str, Any]] = {}\n\n    def add_interface(self, iface: Interface):\n        self.interfaces[iface.name] = iface\n\n    def get_interface(self, name: str) -> Optional[Interface]:\n        return self.interfaces.get(name)\n\n    def get_interface_by_ip(self, ip_str: str) -> Optional[Interface]:\n        for iface in self.interfaces.values():\n            if iface.ip_address == ip_str:\n                return iface\n        return None\n\n    def get_first_operational_interface(self) -> Optional[Interface]:\n        for iface in self.interfaces.values():\n            if iface.is_operational:\n                return iface\n        return None\n\n    def update_arp_cache(self, ip_str: str, mac_str: str, arp_type: str = \"DYNAMIC\"):\n        if ip_str and mac_str and mac_str.upper() != BROADCAST_MAC:\n            self.arp_cache[ip_str] = {\n                \"ip\": ip_str,\n                \"mac\": mac_str.upper(),\n                \"type\": arp_type,\n                \"timestamp\": time.time(),\n                \"age_seconds\": 0\n            }\n\n    def clear_arp_cache(self):\n        self.arp_cache.clear()\n\n    def get_arp_entry(self, ip_str: str) -> Optional[str]:\n        entry = self.arp_cache.get(ip_str)\n        if entry:\n            return entry[\"mac\"]\n        return None\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"id\": self.id,\n            \"name\": self.name,\n            \"device_type\": self.device_type,\n            \"x\": self.x,\n            \"y\": self.y,\n            \"interfaces\": {k: v.to_dict() for k, v in self.interfaces.items()},\n            \"arp_cache\": list(self.arp_cache.values())\n        }\n\n\nclass Host(Device):\n    \"\"\"Represents an End Device: PC, Laptop, or Server.\"\"\"\n    def __init__(\n        self,\n        id: str,\n        name: str,\n        device_type: str = \"pc\",\n        x: float = 0.0,\n        y: float = 0.0,\n        default_gateway: Optional[str] = None\n    ):\n        super().__init__(id, name, device_type, x, y)\n        self.default_gateway = default_gateway\n        self.services = {\"http\": True} if device_type == \"server\" else {}\n\n    def to_dict(self) -> Dict[str, Any]:\n        res = super().to_dict()\n        res[\"default_gateway\"] = self.default_gateway\n        res[\"services\"] = self.services\n        return res\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Host\":\n        host = cls(\n            id=data[\"id\"],\n            name=data[\"name\"],\n            device_type=data.get(\"device_type\", \"pc\"),\n            x=data.get(\"x\", 0.0),\n            y=data.get(\"y\", 0.0),\n            default_gateway=data.get(\"default_gateway\")\n        )\n        for iface_data in data.get(\"interfaces\", {}).values():\n            host.add_interface(Interface.from_dict(iface_data))\n        for arp in data.get(\"arp_cache\", []):\n            host.update_arp_cache(arp[\"ip\"], arp[\"mac\"], arp.get(\"type\", \"DYNAMIC\"))\n        host.services = data.get(\"services\", {})\n        return host\n\n\nclass Switch(Device):\n    \"\"\"Represents a Layer 2 Ethernet Switch.\"\"\"\n    def __init__(\n        self,\n        id: str,\n        name: str,\n        x: float = 0.0,\n        y: float = 0.0\n    ):\n        super().__init__(id, name, \"switch\", x, y)\n        # MAC forwarding table: mac -> {\"port\": str, \"timestamp\": float, \"type\": \"DYNAMIC\"}\n        self.mac_table: Dict[str, Dict[str, Any]] = {}\n\n    def learn_mac(self, mac_str: str, port_name: str):\n        mac_clean = mac_str.upper()\n        if mac_clean not in (BROADCAST_MAC, ZERO_MAC):\n            self.mac_table[mac_clean] = {\n                \"mac\": mac_clean,\n                \"port\": port_name,\n                \"timestamp\": time.time(),\n                \"type\": \"DYNAMIC\",\n                \"age_seconds\": 0\n            }\n\n    def clear_mac_table(self):\n        self.mac_table.clear()\n\n    def lookup_mac(self, mac_str: str) -> Optional[str]:\n        entry = self.mac_table.get(mac_str.upper())\n        if entry:\n            return entry[\"port\"]\n        return None\n\n    def get_forwarding_ports(self, ingress_port: str, dst_mac: str) -> Tuple_Ports:\n        \"\"\"\n        Determine forwarding decision according to Layer 2 Ethernet switching rules:\n        - If broadcast (FF:FF:FF:FF:FF:FF): flood to all active ports EXCEPT ingress.\n        - If learned destination MAC:\n          - If learned port == ingress: filter/drop (do not send back out ingress port).\n          - If learned port != ingress: forward unicast out that specific port.\n        - If unknown unicast: flood to all active ports EXCEPT ingress.\n        \"\"\"\n        dst_clean = dst_mac.upper()\n        active_ports = [\n            iface.name for iface in self.interfaces.values()\n            if iface.is_operational and iface.name != ingress_port\n        ]\n\n        if dst_clean == BROADCAST_MAC:\n            return \"FLOOD_BROADCAST\", active_ports\n\n        learned_port = self.lookup_mac(dst_clean)\n        if learned_port:\n            if learned_port == ingress_port:\n                # Filter: same segment\n                return \"FILTER_SAME_PORT\", []\n            target_iface = self.get_interface(learned_port)\n            if target_iface and target_iface.is_operational:\n                return \"FORWARD_UNICAST\", [learned_port]\n            else:\n                return \"DROP_PORT_DOWN\", []\n        \n        # Unknown Unicast Flooding\n        return \"FLOOD_UNKNOWN_UNICAST\", active_ports\n\n    def to_dict(self) -> Dict[str, Any]:\n        res = super().to_dict()\n        res[\"mac_table\"] = list(self.mac_table.values())\n        return res\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Switch\":\n        sw = cls(\n            id=data[\"id\"],\n            name=data[\"name\"],\n            x=data.get(\"x\", 0.0),\n            y=data.get(\"y\", 0.0)\n        )\n        for iface_data in data.get(\"interfaces\", {}).values():\n            sw.add_interface(Interface.from_dict(iface_data))\n        for entry in data.get(\"mac_table\", []):\n            sw.mac_table[entry[\"mac\"].upper()] = {\n                \"mac\": entry[\"mac\"].upper(),\n                \"port\": entry[\"port\"],\n                \"timestamp\": entry.get(\"timestamp\", time.time()),\n                \"type\": entry.get(\"type\", \"DYNAMIC\"),\n                \"age_seconds\": 0\n            }\n        return sw\n\n\nTuple_Ports = tuple[str, List[str]]\n\n\nclass Router(Device):\n    \"\"\"Represents a Layer 3 IPv4 Router.\"\"\"\n    def __init__(\n        self,\n        id: str,\n        name: str,\n        x: float = 0.0,\n        y: float = 0.0\n    ):\n        super().__init__(id, name, \"router\", x, y)\n        self.static_routes: List[Route] = []\n\n    def add_static_route(self, network: str, mask: str, next_hop: Optional[str] = None, interface_name: Optional[str] = None, metric: int = 1):\n        # Prevent exact duplicate route\n        self.static_routes = [\n            r for r in self.static_routes\n            if not (r.network == network and r.mask == mask and r.next_hop == next_hop)\n        ]\n        self.static_routes.append(Route(network, mask, next_hop, interface_name, metric, \"S\"))\n\n    def remove_static_route(self, network: str, mask: str, next_hop: Optional[str] = None):\n        self.static_routes = [\n            r for r in self.static_routes\n            if not (r.network == network and r.mask == mask and (next_hop is None or r.next_hop == next_hop))\n        ]\n\n    def get_all_routes(self) -> List[Route]:\n        \"\"\"\n        Dynamically synthesize routing table containing:\n        1. Directly connected routes (\"C\") for operational interfaces with IP.\n        2. Configured static routes (\"S\") and default routes (\"S*\").\n        \"\"\"\n        routes: List[Route] = []\n        \n        # Directly Connected Routes\n        for iface in self.interfaces.values():\n            if iface.admin_up and iface.ip_address and iface.subnet_mask:\n                net_addr = iface.get_network_address()\n                if net_addr:\n                    routes.append(Route(\n                        network=net_addr,\n                        mask=iface.subnet_mask,\n                        next_hop=None,\n                        interface_name=iface.name,\n                        metric=0,\n                        route_type=\"C\"\n                    ))\n\n        # Static Routes\n        routes.extend(self.static_routes)\n        return routes\n\n    def find_best_route(self, dest_ip_str: str) -> Optional[Route]:\n        \"\"\"\n        Perform Longest-Prefix-Match (LPM) routing table lookup.\n        Matches against all connected and static routes.\n        Returns the route with the highest prefix length.\n        Ties are broken by lowest administrative metric.\n        \"\"\"\n        matching_routes = [r for r in self.get_all_routes() if r.matches(dest_ip_str)]\n        if not matching_routes:\n            return None\n\n        # Sort descending by prefix length, then ascending by metric\n        matching_routes.sort(key=lambda r: (r.prefix, -r.metric), reverse=True)\n        return matching_routes[0]\n\n    def to_dict(self) -> Dict[str, Any]:\n        res = super().to_dict()\n        res[\"static_routes\"] = [r.to_dict() for r in self.static_routes]\n        res[\"routing_table\"] = [r.to_dict() for r in self.get_all_routes()]\n        return res\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Router\":\n        router = cls(\n            id=data[\"id\"],\n            name=data[\"name\"],\n            x=data.get(\"x\", 0.0),\n            y=data.get(\"y\", 0.0)\n        )\n        for iface_data in data.get(\"interfaces\", {}).values():\n            router.add_interface(Interface.from_dict(iface_data))\n        for r_data in data.get(\"static_routes\", []):\n            router.add_static_route(\n                network=r_data[\"network\"],\n                mask=r_data[\"mask\"],\n                next_hop=r_data.get(\"next_hop\"),\n                interface_name=r_data.get(\"interface_name\"),\n                metric=r_data.get(\"metric\", 1)\n            )\n        for arp in data.get(\"arp_cache\", []):\n            router.update_arp_cache(arp[\"ip\"], arp[\"mac\"], arp.get(\"type\", \"DYNAMIC\"))\n        return router\n\n\nclass Hub(Device):\n    \"\"\"Represents a Physical Layer 1 Multi-port Repeater.\"\"\"\n    def __init__(\n        self,\n        id: str,\n        name: str,\n        x: float = 0.0,\n        y: float = 0.0\n    ):\n        super().__init__(id, name, \"hub\", x, y)\n\n    def get_forwarding_ports(self, ingress_port: str) -> List[str]:\n        \"\"\"Floods received signal to all operational ports except the ingress port.\"\"\"\n        return [\n            iface.name for iface in self.interfaces.values()\n            if iface.is_operational and iface.name != ingress_port\n        ]\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Hub\":\n        hub = cls(\n            id=data[\"id\"],\n            name=data[\"name\"],\n            x=data.get(\"x\", 0.0),\n            y=data.get(\"y\", 0.0)\n        )\n        for iface_data in data.get(\"interfaces\", {}).values():\n            hub.add_interface(Interface.from_dict(iface_data))\n        return hub\n",
  "engine.py": "\"\"\"\nDiscrete-Event Simulation Engine for NetForge.\n\nExecutes deterministic, step-by-step network simulations for ARP,\nEthernet switching, IPv4 routing, ICMP ping, and traceroute,\ngenerating inspectable protocol traces with pedagogical explanations.\n\"\"\"\n\nfrom typing import List, Dict, Optional, Any, Tuple\nimport copy\nfrom netforge.addressing import is_same_subnet\nfrom netforge.protocols import (\n    BROADCAST_MAC, ZERO_MAC, EthernetFrame, ARPPacket, IPv4Packet, ICMPPacket,\n    ETHERTYPE_ARP, ETHERTYPE_IPV4, ARP_OP_REQUEST, ARP_OP_REPLY,\n    ICMP_ECHO_REQUEST, ICMP_ECHO_REPLY, ICMP_TIME_EXCEEDED, ICMP_DEST_UNREACHABLE,\n    ICMP_CODE_TTL_EXPIRED, ICMP_CODE_NET_UNREACHABLE, ICMP_CODE_HOST_UNREACHABLE\n)\nfrom netforge.devices import Host, Switch, Router, Hub, Interface\nfrom netforge.topology import Topology\n\n\nclass SimulationEvent:\n    def __init__(\n        self,\n        event_id: int,\n        step: int,\n        event_type: str,\n        device_id: str,\n        device_name: str,\n        interface_name: Optional[str] = None,\n        target_device_id: Optional[str] = None,\n        target_device_name: Optional[str] = None,\n        target_interface_name: Optional[str] = None,\n        link_id: Optional[str] = None,\n        frame: Optional[EthernetFrame] = None,\n        summary: str = \"\",\n        explanation: str = \"\",\n        status: str = \"INFO\",\n        metadata: Optional[Dict[str, Any]] = None\n    ):\n        self.event_id = event_id\n        self.step = step\n        self.event_type = event_type\n        self.device_id = device_id\n        self.device_name = device_name\n        self.interface_name = interface_name\n        self.target_device_id = target_device_id\n        self.target_device_name = target_device_name\n        self.target_interface_name = target_interface_name\n        self.link_id = link_id\n        self.frame = frame\n        self.summary = summary\n        self.explanation = explanation\n        self.status = status\n        self.metadata = metadata or {}\n\n    def to_dict(self) -> Dict[str, Any]:\n        frame_dict = self.frame.to_dict() if self.frame else None\n        return {\n            \"event_id\": self.event_id,\n            \"step\": self.step,\n            \"event_type\": self.event_type,\n            \"device_id\": self.device_id,\n            \"device_name\": self.device_name,\n            \"interface_name\": self.interface_name,\n            \"target_device_id\": self.target_device_id,\n            \"target_device_name\": self.target_device_name,\n            \"target_interface_name\": self.target_interface_name,\n            \"link_id\": self.link_id,\n            \"frame\": frame_dict,\n            \"summary\": self.summary,\n            \"explanation\": self.explanation,\n            \"status\": self.status,\n            \"metadata\": self.metadata,\n        }\n\n\nclass SimulationEngine:\n    def __init__(self, topology: Topology):\n        self.topology = topology\n        self.events: List[SimulationEvent] = []\n        self._next_event_id = 1\n        self._current_step = 0\n        self.queue: List[Dict[str, Any]] = []\n        self.is_paused = False\n        # Buffer packets waiting for ARP resolution: (device_id, next_hop_ip) -> [(iface_name, ip_pkt)]\n        self.pending_arp: Dict[Tuple[str, str], List[Tuple[str, IPv4Packet]]] = {}\n\n    def reset(self):\n        \"\"\"Reset the simulation event history and queue.\"\"\"\n        self.events.clear()\n        self.queue.clear()\n        self._next_event_id = 1\n        self._current_step = 0\n        self.is_paused = False\n        self.pending_arp.clear()\n\n    def _record_event(\n        self,\n        event_type: str,\n        device_id: str,\n        device_name: str,\n        interface_name: Optional[str] = None,\n        target_device_id: Optional[str] = None,\n        target_device_name: Optional[str] = None,\n        target_interface_name: Optional[str] = None,\n        link_id: Optional[str] = None,\n        frame: Optional[EthernetFrame] = None,\n        summary: str = \"\",\n        explanation: str = \"\",\n        status: str = \"INFO\",\n        metadata: Optional[Dict[str, Any]] = None\n    ) -> SimulationEvent:\n        event = SimulationEvent(\n            event_id=self._next_event_id,\n            step=self._current_step,\n            event_type=event_type,\n            device_id=device_id,\n            device_name=device_name,\n            interface_name=interface_name,\n            target_device_id=target_device_id,\n            target_device_name=target_device_name,\n            target_interface_name=target_interface_name,\n            link_id=link_id,\n            frame=frame,\n            summary=summary,\n            explanation=explanation,\n            status=status,\n            metadata=metadata\n        )\n        self._next_event_id += 1\n        self.events.append(event)\n        return event\n\n    def send_frame(self, source_dev_id: str, source_iface_name: str, frame: EthernetFrame):\n        \"\"\"Enqueue a frame transmission from a source interface over its connected link.\"\"\"\n        src_dev = self.topology.devices.get(source_dev_id)\n        if not src_dev:\n            return\n        src_iface = src_dev.get_interface(source_iface_name)\n        if not src_iface:\n            return\n\n        if not src_iface.admin_up:\n            self._record_event(\n                event_type=\"DROP_INTERFACE_DOWN\",\n                device_id=source_dev_id,\n                device_name=src_dev.name,\n                interface_name=source_iface_name,\n                frame=frame,\n                summary=f\"{src_dev.name}: Interface {source_iface_name} is administratively down\",\n                explanation=f\"Cannot transmit frame because interface {source_iface_name} is shutdown.\",\n                status=\"DROP\"\n            )\n            return\n\n        link = self.topology.get_link_by_interface(source_dev_id, source_iface_name)\n        if not link or not link.is_up:\n            self._record_event(\n                event_type=\"DROP_LINK_DOWN\",\n                device_id=source_dev_id,\n                device_name=src_dev.name,\n                interface_name=source_iface_name,\n                frame=frame,\n                summary=f\"{src_dev.name}: Interface {source_iface_name} cable disconnected / link down\",\n                explanation=f\"Cannot transmit frame because virtual link on {source_iface_name} is disconnected or down.\",\n                status=\"DROP\"\n            )\n            return\n\n        other = link.get_other_endpoint(source_dev_id, source_iface_name)\n        if not other:\n            return\n        dst_dev_id, dst_iface_name = other\n        dst_dev = self.topology.devices.get(dst_dev_id)\n\n        self.queue.append({\n            \"type\": \"TRANSMIT_FRAME\",\n            \"src_dev_id\": source_dev_id,\n            \"src_iface\": source_iface_name,\n            \"dst_dev_id\": dst_dev_id,\n            \"dst_iface\": dst_iface_name,\n            \"link_id\": link.id,\n            \"frame\": frame\n        })\n\n    def step(self) -> Optional[SimulationEvent]:\n        \"\"\"Execute one simulation action from the discrete queue.\"\"\"\n        if not self.queue:\n            return None\n\n        self._current_step += 1\n        task = self.queue.pop(0)\n        action_type = task[\"type\"]\n\n        if action_type == \"TRANSMIT_FRAME\":\n            return self._handle_transmit_frame(task)\n        elif action_type == \"PROCESS_FRAME\":\n            return self._handle_process_frame(task)\n\n        return None\n\n    def run_all(self, max_steps: int = 100) -> List[SimulationEvent]:\n        \"\"\"Run all queued simulation events until empty or max_steps reached.\"\"\"\n        starting_index = len(self.events)\n        steps_executed = 0\n        while self.queue and steps_executed < max_steps:\n            self.step()\n            steps_executed += 1\n        return self.events[starting_index:]\n\n    def _handle_transmit_frame(self, task: Dict[str, Any]) -> SimulationEvent:\n        src_dev = self.topology.devices[task[\"src_dev_id\"]]\n        dst_dev = self.topology.devices[task[\"dst_dev_id\"]]\n        frame = task[\"frame\"]\n        link_id = task[\"link_id\"]\n\n        is_broadcast = frame.is_broadcast()\n        frame_type = frame.ethertype\n\n        summary = f\"{src_dev.name} ({task['src_iface']}) -> {dst_dev.name} ({task['dst_iface']}): Transmitting {frame_type} frame\"\n        explanation = (\n            f\"Transmitting Layer 2 Ethernet frame across link {link_id}. \"\n            f\"Source MAC: {frame.src_mac}, Destination MAC: {frame.dst_mac}.\"\n        )\n\n        event = self._record_event(\n            event_type=\"FRAME_TRANSMIT\",\n            device_id=src_dev.id,\n            device_name=src_dev.name,\n            interface_name=task[\"src_iface\"],\n            target_device_id=dst_dev.id,\n            target_device_name=dst_dev.name,\n            target_interface_name=task[\"dst_iface\"],\n            link_id=link_id,\n            frame=frame,\n            summary=summary,\n            explanation=explanation,\n            status=\"INFO\",\n            metadata={\"is_broadcast\": is_broadcast, \"ethertype\": frame_type}\n        )\n\n        # Enqueue reception by destination device\n        self.queue.append({\n            \"type\": \"PROCESS_FRAME\",\n            \"dev_id\": dst_dev.id,\n            \"ingress_iface\": task[\"dst_iface\"],\n            \"link_id\": link_id,\n            \"frame\": frame\n        })\n        return event\n\n    def _handle_process_frame(self, task: Dict[str, Any]) -> SimulationEvent:\n        dev = self.topology.devices[task[\"dev_id\"]]\n        ingress_iface_name = task[\"ingress_iface\"]\n        ingress_iface = dev.get_interface(ingress_iface_name)\n        frame: EthernetFrame = task[\"frame\"]\n\n        if not ingress_iface or not ingress_iface.is_operational:\n            return self._record_event(\n                event_type=\"DROP_PORT_DOWN\",\n                device_id=dev.id,\n                device_name=dev.name,\n                interface_name=ingress_iface_name,\n                frame=frame,\n                summary=f\"{dev.name}: Ingress port {ingress_iface_name} is down\",\n                explanation=\"Frame dropped because the receiving interface is shutdown or unlinked.\",\n                status=\"DROP\"\n            )\n\n        if isinstance(dev, Switch):\n            return self._handle_switch_frame(dev, ingress_iface_name, frame)\n        elif isinstance(dev, Hub):\n            return self._handle_hub_frame(dev, ingress_iface_name, frame)\n        elif isinstance(dev, Router):\n            return self._handle_router_frame(dev, ingress_iface_name, frame)\n        elif isinstance(dev, Host):\n            return self._handle_host_frame(dev, ingress_iface_name, frame)\n        return None\n\n    def _handle_switch_frame(self, switch: Switch, ingress_port: str, frame: EthernetFrame) -> SimulationEvent:\n        # Step 1: MAC learning\n        learned_mac = frame.src_mac.upper()\n        old_port = switch.lookup_mac(learned_mac)\n        switch.learn_mac(learned_mac, ingress_port)\n\n        learn_expl = f\"Switch learned that MAC {learned_mac} is reachable on port {ingress_port}.\"\n        if old_port and old_port != ingress_port:\n            learn_expl += f\" (Updated from previous port {old_port}).\"\n\n        # Step 2: Forwarding decision\n        decision, ports = switch.get_forwarding_ports(ingress_port, frame.dst_mac)\n\n        if decision == \"FILTER_SAME_PORT\":\n            return self._record_event(\n                event_type=\"SWITCH_FILTER\",\n                device_id=switch.id,\n                device_name=switch.name,\n                interface_name=ingress_port,\n                frame=frame,\n                summary=f\"{switch.name}: Filtered frame destined to {frame.dst_mac} on same port {ingress_port}\",\n                explanation=f\"{learn_expl} The destination MAC was learned on the ingress port {ingress_port}, so the switch filtered (dropped) the frame to avoid a loop.\",\n                status=\"INFO\",\n                metadata={\"mac_table\": list(switch.mac_table.values())}\n            )\n\n        if decision == \"FORWARD_UNICAST\":\n            out_port = ports[0]\n            self.send_frame(switch.id, out_port, frame)\n            return self._record_event(\n                event_type=\"SWITCH_FORWARD\",\n                device_id=switch.id,\n                device_name=switch.name,\n                interface_name=ingress_port,\n                target_interface_name=out_port,\n                frame=frame,\n                summary=f\"{switch.name}: Unicast forwarded frame to {frame.dst_mac} out port {out_port}\",\n                explanation=f\"{learn_expl} Destination MAC {frame.dst_mac} was found in the forwarding table; forwarding out port {out_port} only.\",\n                status=\"SUCCESS\",\n                metadata={\"forwarded_port\": out_port, \"mac_table\": list(switch.mac_table.values())}\n            )\n\n        # Flooding (Broadcast or Unknown Unicast)\n        for out_port in ports:\n            self.send_frame(switch.id, out_port, copy.deepcopy(frame))\n\n        flood_reason = \"broadcast\" if frame.is_broadcast() else \"unknown unicast\"\n        return self._record_event(\n            event_type=\"SWITCH_FLOOD\",\n            device_id=switch.id,\n            device_name=switch.name,\n            interface_name=ingress_port,\n            frame=frame,\n            summary=f\"{switch.name}: Flooded {flood_reason} frame to ports: {', '.join(ports) or 'None'}\",\n            explanation=f\"{learn_expl} Frame is a {flood_reason}; flooding out all active ports except ingress port {ingress_port}.\",\n            status=\"INFO\",\n            metadata={\"flooded_ports\": ports, \"mac_table\": list(switch.mac_table.values())}\n        )\n\n    def _handle_hub_frame(self, hub: Hub, ingress_port: str, frame: EthernetFrame) -> SimulationEvent:\n        ports = hub.get_forwarding_ports(ingress_port)\n        for out_port in ports:\n            self.send_frame(hub.id, out_port, copy.deepcopy(frame))\n        return self._record_event(\n            event_type=\"HUB_FLOOD\",\n            device_id=hub.id,\n            device_name=hub.name,\n            interface_name=ingress_port,\n            frame=frame,\n            summary=f\"{hub.name}: Physical Layer 1 repeated signal to ports: {', '.join(ports)}\",\n            explanation=\"Hubs operate at Layer 1; they do not inspect MAC addresses or maintain a MAC table. Every incoming signal is repeated to all other ports.\",\n            status=\"INFO\"\n        )\n\n    def _handle_host_frame(self, host: Host, ingress_port: str, frame: EthernetFrame) -> SimulationEvent:\n        iface = host.get_interface(ingress_port)\n        if not iface:\n            return None\n\n        # Layer 2 MAC check: must match host MAC or broadcast\n        if not frame.is_broadcast() and frame.dst_mac.upper() != iface.mac_address.upper():\n            return self._record_event(\n                event_type=\"DROP_L2_MISMATCH\",\n                device_id=host.id,\n                device_name=host.name,\n                interface_name=ingress_port,\n                frame=frame,\n                summary=f\"{host.name}: Dropped frame; destination MAC {frame.dst_mac} != {iface.mac_address}\",\n                explanation=f\"Network interface card (NIC) rejected frame because destination MAC {frame.dst_mac} does not match host MAC and is not broadcast.\",\n                status=\"DROP\"\n            )\n\n        # Process Layer 3 Protocol\n        if frame.ethertype == ETHERTYPE_ARP:\n            return self._handle_host_arp(host, iface, frame)\n        elif frame.ethertype == ETHERTYPE_IPV4:\n            return self._handle_host_ipv4(host, iface, frame)\n\n        return None\n\n    def _handle_host_arp(self, host: Host, iface: Interface, frame: EthernetFrame) -> SimulationEvent:\n        arp: ARPPacket = frame.payload if isinstance(frame.payload, ARPPacket) else ARPPacket.from_dict(frame.payload)\n        \n        # Learn sender in ARP cache\n        host.update_arp_cache(arp.sender_ip, arp.sender_mac)\n\n        if arp.operation == ARP_OP_REQUEST:\n            # Check if requested target IP matches our interface IP\n            if arp.target_ip == iface.ip_address:\n                # Generate ARP Reply unicast\n                reply_arp = ARPPacket(\n                    operation=ARP_OP_REPLY,\n                    sender_mac=iface.mac_address,\n                    sender_ip=iface.ip_address,\n                    target_mac=arp.sender_mac,\n                    target_ip=arp.sender_ip\n                )\n                reply_frame = EthernetFrame(\n                    src_mac=iface.mac_address,\n                    dst_mac=arp.sender_mac,\n                    ethertype=ETHERTYPE_ARP,\n                    payload=reply_arp\n                )\n                self.send_frame(host.id, iface.name, reply_frame)\n                return self._record_event(\n                    event_type=\"ARP_REPLY_SENT\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    frame=reply_frame,\n                    summary=f\"{host.name}: Target IP {arp.target_ip} matched! Sending ARP Reply with MAC {iface.mac_address}\",\n                    explanation=f\"Host verified that the ARP request matches its configured IP {iface.ip_address}. It cached sender {arp.sender_ip} -> {arp.sender_mac} and is returning a unicast ARP Reply.\",\n                    status=\"SUCCESS\"\n                )\n            else:\n                return self._record_event(\n                    event_type=\"ARP_IGNORED\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    frame=frame,\n                    summary=f\"{host.name}: Ignored ARP Request for {arp.target_ip} (my IP is {iface.ip_address})\",\n                    explanation=f\"Host learned sender {arp.sender_ip} in its ARP cache, but ignored the request because the target IP {arp.target_ip} does not match.\",\n                    status=\"INFO\"\n                )\n\n        elif arp.operation == ARP_OP_REPLY:\n            # Drain any buffered packets for this next-hop IP\n            pending = self.pending_arp.pop((host.id, arp.sender_ip), [])\n            for pending_iface, pending_pkt in pending:\n                p_iface_obj = host.get_interface(pending_iface)\n                if p_iface_obj:\n                    fwd_frame = EthernetFrame(\n                        src_mac=p_iface_obj.mac_address,\n                        dst_mac=arp.sender_mac,\n                        ethertype=ETHERTYPE_IPV4,\n                        payload=pending_pkt\n                    )\n                    self.send_frame(host.id, pending_iface, fwd_frame)\n                    self._record_event(\n                        event_type=\"HOST_FRAME_TRANSMIT\",\n                        device_id=host.id,\n                        device_name=host.name,\n                        interface_name=pending_iface,\n                        frame=fwd_frame,\n                        summary=f\"{host.name}: ARP resolved! Transmitting buffered IPv4 packet to {pending_pkt.dst_ip}\",\n                        explanation=f\"Host received ARP resolution for next-hop {arp.sender_ip} -> {arp.sender_mac} and released the buffered IPv4 packet.\",\n                        status=\"SUCCESS\"\n                    )\n\n            return self._record_event(\n                event_type=\"ARP_REPLY_RECEIVED\",\n                device_id=host.id,\n                device_name=host.name,\n                interface_name=iface.name,\n                frame=frame,\n                summary=f\"{host.name}: Cached ARP resolution: {arp.sender_ip} is at {arp.sender_mac}\",\n                explanation=f\"Host received unicast ARP reply from {arp.sender_ip} and recorded MAC {arp.sender_mac} into its ARP cache.\",\n                status=\"SUCCESS\",\n                metadata={\"arp_cache\": list(host.arp_cache.values())}\n            )\n\n        return None\n\n    def _handle_host_ipv4(self, host: Host, iface: Interface, frame: EthernetFrame) -> SimulationEvent:\n        ip_pkt: IPv4Packet = frame.payload if isinstance(frame.payload, IPv4Packet) else IPv4Packet.from_dict(frame.payload)\n        \n        # Check IP destination\n        if ip_pkt.dst_ip != iface.ip_address:\n            return self._record_event(\n                event_type=\"DROP_IP_MISMATCH\",\n                device_id=host.id,\n                device_name=host.name,\n                interface_name=iface.name,\n                frame=frame,\n                summary=f\"{host.name}: Dropped packet; destination IP {ip_pkt.dst_ip} != {iface.ip_address}\",\n                explanation=f\"Host received an IPv4 packet destined to {ip_pkt.dst_ip}, which does not match host interface IP {iface.ip_address}.\",\n                status=\"DROP\"\n            )\n\n        # ICMP Processing\n        if ip_pkt.protocol == \"ICMP\":\n            icmp: ICMPPacket = ip_pkt.payload if isinstance(ip_pkt.payload, ICMPPacket) else ICMPPacket.from_dict(ip_pkt.payload)\n            \n            if icmp.type == ICMP_ECHO_REQUEST:\n                # Generate ICMP Echo Reply\n                reply_icmp = ICMPPacket(\n                    type=ICMP_ECHO_REPLY,\n                    code=0,\n                    sequence=icmp.sequence,\n                    identifier=icmp.identifier,\n                    payload=icmp.payload\n                )\n                reply_ip = IPv4Packet(\n                    src_ip=iface.ip_address,\n                    dst_ip=ip_pkt.src_ip,\n                    ttl=64,\n                    protocol=\"ICMP\",\n                    payload=reply_icmp\n                )\n                # Next hop resolution for return path\n                self._send_ip_packet_from_host(host, iface, reply_ip)\n                return self._record_event(\n                    event_type=\"ICMP_ECHO_REPLY_SENT\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    summary=f\"{host.name}: Received ICMP Echo Request from {ip_pkt.src_ip}; sending Echo Reply\",\n                    explanation=f\"Host successfully received and validated the ICMP Echo Request. It generated an ICMP Echo Reply packet destined back to {ip_pkt.src_ip}.\",\n                    status=\"SUCCESS\"\n                )\n\n            elif icmp.type == ICMP_ECHO_REPLY:\n                return self._record_event(\n                    event_type=\"PING_SUCCESS\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    frame=frame,\n                    summary=f\"{host.name}: Ping reply received from {ip_pkt.src_ip}! (seq={icmp.sequence}, ttl={ip_pkt.ttl})\",\n                    explanation=f\"ICMP Echo Reply arrived successfully at source host {host.name}. End-to-end network connectivity verified!\",\n                    status=\"SUCCESS\",\n                    metadata={\"src_ip\": ip_pkt.src_ip, \"seq\": icmp.sequence, \"ttl\": ip_pkt.ttl}\n                )\n\n            elif icmp.type == ICMP_TIME_EXCEEDED:\n                return self._record_event(\n                    event_type=\"ICMP_TTL_EXPIRED\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    frame=frame,\n                    summary=f\"{host.name}: Received ICMP Time Exceeded from {ip_pkt.src_ip}\",\n                    explanation=f\"Router at {ip_pkt.src_ip} decremented the packet TTL to 0 and dropped the packet, returning this ICMP Time Exceeded notification.\",\n                    status=\"WARNING\"\n                )\n\n            elif icmp.type == ICMP_DEST_UNREACHABLE:\n                return self._record_event(\n                    event_type=\"ICMP_UNREACHABLE\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    frame=frame,\n                    summary=f\"{host.name}: Received Destination Unreachable from {ip_pkt.src_ip} (Code {icmp.code})\",\n                    explanation=f\"Gateway/router at {ip_pkt.src_ip} reported that the destination network or host could not be reached.\",\n                    status=\"ERROR\"\n                )\n\n        return None\n\n    def _handle_router_frame(self, router: Router, ingress_port: str, frame: EthernetFrame) -> SimulationEvent:\n        ingress_iface = router.get_interface(ingress_port)\n        if not ingress_iface:\n            return None\n\n        # Check Layer 2 destination\n        if not frame.is_broadcast() and frame.dst_mac.upper() != ingress_iface.mac_address.upper():\n            return self._record_event(\n                event_type=\"DROP_ROUTER_L2_MISMATCH\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=ingress_port,\n                frame=frame,\n                summary=f\"{router.name}: Ingress frame destination MAC {frame.dst_mac} does not match interface {ingress_port}\",\n                explanation=f\"Router interface {ingress_port} has MAC {ingress_iface.mac_address}; rejected frame with dst_mac {frame.dst_mac}.\",\n                status=\"DROP\"\n            )\n\n        if frame.ethertype == ETHERTYPE_ARP:\n            return self._handle_router_arp(router, ingress_iface, frame)\n        elif frame.ethertype == ETHERTYPE_IPV4:\n            return self._handle_router_ipv4(router, ingress_iface, frame)\n\n        return None\n\n    def _handle_router_arp(self, router: Router, ingress_iface: Interface, frame: EthernetFrame) -> SimulationEvent:\n        arp: ARPPacket = frame.payload if isinstance(frame.payload, ARPPacket) else ARPPacket.from_dict(frame.payload)\n        router.update_arp_cache(arp.sender_ip, arp.sender_mac)\n\n        if arp.operation == ARP_OP_REQUEST:\n            if arp.target_ip == ingress_iface.ip_address:\n                reply_arp = ARPPacket(\n                    operation=ARP_OP_REPLY,\n                    sender_mac=ingress_iface.mac_address,\n                    sender_ip=ingress_iface.ip_address,\n                    target_mac=arp.sender_mac,\n                    target_ip=arp.sender_ip\n                )\n                reply_frame = EthernetFrame(\n                    src_mac=ingress_iface.mac_address,\n                    dst_mac=arp.sender_mac,\n                    ethertype=ETHERTYPE_ARP,\n                    payload=reply_arp\n                )\n                self.send_frame(router.id, ingress_iface.name, reply_frame)\n                return self._record_event(\n                    event_type=\"ARP_REPLY_SENT\",\n                    device_id=router.id,\n                    device_name=router.name,\n                    interface_name=ingress_iface.name,\n                    frame=reply_frame,\n                    summary=f\"{router.name}: Responded to ARP Request for gateway IP {ingress_iface.ip_address}\",\n                    explanation=f\"Router confirmed that target IP {arp.target_ip} matches interface {ingress_iface.name}. Responded with MAC {ingress_iface.mac_address}.\",\n                    status=\"SUCCESS\"\n                )\n            else:\n                return self._record_event(\n                    event_type=\"ARP_IGNORED\",\n                    device_id=router.id,\n                    device_name=router.name,\n                    interface_name=ingress_iface.name,\n                    frame=frame,\n                    summary=f\"{router.name}: Ignored ARP Request for {arp.target_ip} on interface {ingress_iface.name}\",\n                    explanation=f\"Router cached sender {arp.sender_ip} -> {arp.sender_mac}, but ignored request because target IP {arp.target_ip} is not configured on interface {ingress_iface.name}.\",\n                    status=\"INFO\"\n                )\n        elif arp.operation == ARP_OP_REPLY:\n            # Drain any buffered packets waiting for this next-hop IP\n            pending = self.pending_arp.pop((router.id, arp.sender_ip), [])\n            for pending_iface, pending_pkt in pending:\n                p_iface_obj = router.get_interface(pending_iface)\n                if p_iface_obj:\n                    fwd_frame = EthernetFrame(\n                        src_mac=p_iface_obj.mac_address,\n                        dst_mac=arp.sender_mac,\n                        ethertype=ETHERTYPE_IPV4,\n                        payload=pending_pkt\n                    )\n                    self.send_frame(router.id, pending_iface, fwd_frame)\n                    self._record_event(\n                        event_type=\"ROUTER_FORWARD\",\n                        device_id=router.id,\n                        device_name=router.name,\n                        interface_name=pending_iface,\n                        frame=fwd_frame,\n                        summary=f\"{router.name}: Transmitting buffered packet to {pending_pkt.dst_ip} via {pending_iface} now that ARP resolved {arp.sender_ip}\",\n                        explanation=f\"Router received ARP resolution for next-hop {arp.sender_ip} -> {arp.sender_mac} and released the buffered IPv4 packet.\",\n                        status=\"SUCCESS\"\n                    )\n\n            return self._record_event(\n                event_type=\"ARP_REPLY_RECEIVED\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=ingress_iface.name,\n                frame=frame,\n                summary=f\"{router.name}: Cached ARP resolution: {arp.sender_ip} is at {arp.sender_mac}\",\n                explanation=f\"Router received unicast ARP reply from {arp.sender_ip} and recorded MAC {arp.sender_mac} into its ARP cache.\",\n                status=\"SUCCESS\",\n                metadata={\"arp_cache\": list(router.arp_cache.values())}\n            )\n\n        return None\n\n    def _handle_router_ipv4(self, router: Router, ingress_iface: Interface, frame: EthernetFrame) -> SimulationEvent:\n        ip_pkt: IPv4Packet = frame.payload if isinstance(frame.payload, IPv4Packet) else IPv4Packet.from_dict(frame.payload)\n\n        # Check if destined for one of the router's own interfaces\n        for iface in router.interfaces.values():\n            if iface.admin_up and iface.ip_address == ip_pkt.dst_ip:\n                # Destined for router itself!\n                if ip_pkt.protocol == \"ICMP\":\n                    icmp: ICMPPacket = ip_pkt.payload if isinstance(ip_pkt.payload, ICMPPacket) else ICMPPacket.from_dict(ip_pkt.payload)\n                    if icmp.type == ICMP_ECHO_REQUEST:\n                        reply_icmp = ICMPPacket(type=ICMP_ECHO_REPLY, sequence=icmp.sequence, identifier=icmp.identifier, payload=icmp.payload)\n                        reply_ip = IPv4Packet(src_ip=iface.ip_address, dst_ip=ip_pkt.src_ip, ttl=64, protocol=\"ICMP\", payload=reply_icmp)\n                        self._forward_router_ip_packet(router, reply_ip)\n                        return self._record_event(\n                            event_type=\"ROUTER_LOCAL_ICMP_REPLY\",\n                            device_id=router.id,\n                            device_name=router.name,\n                            interface_name=iface.name,\n                            summary=f\"{router.name}: Received ping for router IP {iface.ip_address}; sending Echo Reply\",\n                            explanation=f\"Packet destination matches router's own interface IP {iface.ip_address}. Router processes request locally and replies.\",\n                            status=\"SUCCESS\"\n                        )\n\n        # Packet needs to be routed / forwarded!\n        # Step 1: Decrement TTL\n        ip_pkt.ttl -= 1\n        if ip_pkt.ttl <= 0:\n            # TTL Expired!\n            time_exceeded_icmp = ICMPPacket(type=ICMP_TIME_EXCEEDED, code=ICMP_CODE_TTL_EXPIRED, payload=\"Time to live exceeded in transit\")\n            te_ip = IPv4Packet(src_ip=ingress_iface.ip_address, dst_ip=ip_pkt.src_ip, ttl=64, protocol=\"ICMP\", payload=time_exceeded_icmp)\n            self._forward_router_ip_packet(router, te_ip)\n            return self._record_event(\n                event_type=\"ROUTER_TTL_EXPIRED\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=ingress_iface.name,\n                frame=frame,\n                summary=f\"{router.name}: Dropped packet to {ip_pkt.dst_ip}; TTL decremented to 0\",\n                explanation=\"IPv4 Time-To-Live reached 0 during router forwarding. Packet dropped to prevent infinite routing loops; sent ICMP Time Exceeded to source.\",\n                status=\"DROP\"\n            )\n\n        # Step 2: Longest-Prefix-Match Route Lookup\n        route = router.find_best_route(ip_pkt.dst_ip)\n        if not route:\n            # No route to host\n            unreach_icmp = ICMPPacket(type=ICMP_DEST_UNREACHABLE, code=ICMP_CODE_NET_UNREACHABLE, payload=\"Destination network unreachable\")\n            unreach_ip = IPv4Packet(src_ip=ingress_iface.ip_address, dst_ip=ip_pkt.src_ip, ttl=64, protocol=\"ICMP\", payload=unreach_icmp)\n            self._forward_router_ip_packet(router, unreach_ip)\n            return self._record_event(\n                event_type=\"ROUTER_NO_ROUTE\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=ingress_iface.name,\n                frame=frame,\n                summary=f\"{router.name}: No route to destination {ip_pkt.dst_ip}; dropped packet\",\n                explanation=f\"Router routing table has no matching route (connected or static) for destination IP {ip_pkt.dst_ip}. Dropped packet and sent ICMP Network Unreachable.\",\n                status=\"DROP\",\n                metadata={\"routing_table\": [r.to_dict() for r in router.get_all_routes()]}\n            )\n\n        # Step 3: Forward packet out egress interface\n        egress_iface = router.get_interface(route.interface_name)\n        if not egress_iface or not egress_iface.is_operational:\n            return self._record_event(\n                event_type=\"ROUTER_EGRESS_DOWN\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=route.interface_name,\n                frame=frame,\n                summary=f\"{router.name}: Egress interface {route.interface_name} is down\",\n                explanation=f\"Route matched interface {route.interface_name}, but that interface is down or disconnected.\",\n                status=\"DROP\"\n            )\n\n        # Determine next-hop IP for Layer 2 resolution\n        next_hop_ip = route.next_hop if route.next_hop else ip_pkt.dst_ip\n\n        # Check router ARP cache for next hop\n        cached_mac = router.get_arp_entry(next_hop_ip)\n        if not cached_mac:\n            # Buffer packet to transmit once ARP resolution completes\n            self.pending_arp.setdefault((router.id, next_hop_ip), []).append((egress_iface.name, copy.deepcopy(ip_pkt)))\n            # Need to ARP for next hop\n            arp_req = ARPPacket(\n                operation=ARP_OP_REQUEST,\n                sender_mac=egress_iface.mac_address,\n                sender_ip=egress_iface.ip_address,\n                target_mac=ZERO_MAC,\n                target_ip=next_hop_ip\n            )\n            arp_frame = EthernetFrame(\n                src_mac=egress_iface.mac_address,\n                dst_mac=BROADCAST_MAC,\n                ethertype=ETHERTYPE_ARP,\n                payload=arp_req\n            )\n            self.send_frame(router.id, egress_iface.name, arp_frame)\n            return self._record_event(\n                event_type=\"ROUTER_ARP_REQUEST\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=egress_iface.name,\n                frame=arp_frame,\n                summary=f\"{router.name}: Route matched {route.network}/{route.prefix}; ARP cache miss for next-hop {next_hop_ip}, broadcasting ARP Request\",\n                explanation=f\"Router matched route {route.network}/{route.prefix} via {route.interface_name}. Because next-hop {next_hop_ip} is not in router's ARP table, router broadcasts an ARP Request.\",\n                status=\"INFO\",\n                metadata={\"route\": route.to_dict()}\n            )\n        else:\n            # Encapsulate with next hop MAC\n            fwd_frame = EthernetFrame(\n                src_mac=egress_iface.mac_address,\n                dst_mac=cached_mac,\n                ethertype=ETHERTYPE_IPV4,\n                payload=ip_pkt\n            )\n            self.send_frame(router.id, egress_iface.name, fwd_frame)\n            return self._record_event(\n                event_type=\"ROUTER_FORWARD\",\n                device_id=router.id,\n                device_name=router.name,\n                interface_name=ingress_iface.name,\n                target_interface_name=egress_iface.name,\n                frame=fwd_frame,\n                summary=f\"{router.name}: Forwarded IPv4 packet to {ip_pkt.dst_ip} via {egress_iface.name} (next-hop {next_hop_ip}, TTL={ip_pkt.ttl})\",\n                explanation=f\"Router selected route {route.network}/{route.prefix} (type: {route.route_type}) using Longest-Prefix-Match. Decremented TTL to {ip_pkt.ttl} and encapsulated frame to next-hop MAC {cached_mac}.\",\n                status=\"SUCCESS\",\n                metadata={\"route\": route.to_dict(), \"next_hop_ip\": next_hop_ip, \"next_hop_mac\": cached_mac}\n            )\n\n    def _forward_router_ip_packet(self, router: Router, ip_pkt: IPv4Packet):\n        route = router.find_best_route(ip_pkt.dst_ip)\n        if not route:\n            return\n        egress_iface = router.get_interface(route.interface_name)\n        if not egress_iface or not egress_iface.is_operational:\n            return\n        next_hop_ip = route.next_hop if route.next_hop else ip_pkt.dst_ip\n        cached_mac = router.get_arp_entry(next_hop_ip)\n        if not cached_mac:\n            self.pending_arp.setdefault((router.id, next_hop_ip), []).append((egress_iface.name, copy.deepcopy(ip_pkt)))\n            arp_req = ARPPacket(operation=ARP_OP_REQUEST, sender_mac=egress_iface.mac_address, sender_ip=egress_iface.ip_address, target_mac=ZERO_MAC, target_ip=next_hop_ip)\n            arp_frame = EthernetFrame(src_mac=egress_iface.mac_address, dst_mac=BROADCAST_MAC, ethertype=ETHERTYPE_ARP, payload=arp_req)\n            self.send_frame(router.id, egress_iface.name, arp_frame)\n        else:\n            frame = EthernetFrame(src_mac=egress_iface.mac_address, dst_mac=cached_mac, ethertype=ETHERTYPE_IPV4, payload=ip_pkt)\n            self.send_frame(router.id, egress_iface.name, frame)\n\n    def _send_ip_packet_from_host(self, host: Host, iface: Interface, ip_pkt: IPv4Packet):\n        \"\"\"Prepare and transmit an IPv4 packet from a host, performing subnet check and ARP resolution.\"\"\"\n        # Determine if destination is on the local subnet or remote\n        if is_same_subnet(iface.ip_address, ip_pkt.dst_ip, iface.subnet_mask):\n            next_hop_ip = ip_pkt.dst_ip\n            is_local = True\n        else:\n            if not host.default_gateway:\n                self._record_event(\n                    event_type=\"DROP_NO_GATEWAY\",\n                    device_id=host.id,\n                    device_name=host.name,\n                    interface_name=iface.name,\n                    summary=f\"{host.name}: Cannot reach remote destination {ip_pkt.dst_ip}; no default gateway configured\",\n                    explanation=f\"Destination {ip_pkt.dst_ip} is outside local subnet ({iface.ip_address}/{iface.subnet_mask}), and host {host.name} has no default gateway configured.\",\n                    status=\"ERROR\"\n                )\n                return\n            next_hop_ip = host.default_gateway\n            is_local = False\n\n        cached_mac = host.get_arp_entry(next_hop_ip)\n        if not cached_mac:\n            # Buffer packet to transmit once ARP resolution completes\n            self.pending_arp.setdefault((host.id, next_hop_ip), []).append((iface.name, copy.deepcopy(ip_pkt)))\n            # Send ARP Request\n            arp_req = ARPPacket(\n                operation=ARP_OP_REQUEST,\n                sender_mac=iface.mac_address,\n                sender_ip=iface.ip_address,\n                target_mac=ZERO_MAC,\n                target_ip=next_hop_ip\n            )\n            arp_frame = EthernetFrame(\n                src_mac=iface.mac_address,\n                dst_mac=BROADCAST_MAC,\n                ethertype=ETHERTYPE_ARP,\n                payload=arp_req\n            )\n            self.send_frame(host.id, iface.name, arp_frame)\n            dest_desc = \"destination\" if is_local else f\"default gateway {host.default_gateway}\"\n            self._record_event(\n                event_type=\"ARP_REQUEST_INITIATED\",\n                device_id=host.id,\n                device_name=host.name,\n                interface_name=iface.name,\n                frame=arp_frame,\n                summary=f\"{host.name}: ARP cache miss for {next_hop_ip}; broadcasting ARP Request out {iface.name}\",\n                explanation=(\n                    f\"To deliver packet to {ip_pkt.dst_ip}, host must know the Layer 2 MAC address of {dest_desc}. \"\n                    f\"Because {next_hop_ip} is not in the ARP cache, {host.name} initiates Address Resolution Protocol.\"\n                ),\n                status=\"INFO\"\n            )\n        else:\n            # Directly transmit IPv4 packet encapsulated in Ethernet frame\n            fwd_frame = EthernetFrame(\n                src_mac=iface.mac_address,\n                dst_mac=cached_mac,\n                ethertype=ETHERTYPE_IPV4,\n                payload=ip_pkt\n            )\n            self.send_frame(host.id, iface.name, fwd_frame)\n\n    def ping(self, source_host_id: str, target_ip_str: str, count: int = 1) -> List[SimulationEvent]:\n        \"\"\"\n        Initiate an interactive ping from source host to target IP.\n        Executes ARP resolution and ICMP Echo transmission step-by-step.\n        \"\"\"\n        host = self.topology.devices.get(source_host_id)\n        if not host or not isinstance(host, Host):\n            raise ValueError(f\"Source device {source_host_id} is not an end host (PC/Laptop/Server)\")\n\n        iface = host.get_first_operational_interface()\n        if not iface:\n            self._record_event(\n                event_type=\"DROP_NO_INTERFACE\",\n                device_id=host.id,\n                device_name=host.name,\n                summary=f\"{host.name}: No operational network interface found\",\n                explanation=f\"{host.name} has no connected and enabled interface with IP configuration.\",\n                status=\"DROP\"\n            )\n            return self.events\n\n        if not iface.ip_address or not iface.subnet_mask:\n            self._record_event(\n                event_type=\"DROP_NO_IP\",\n                device_id=host.id,\n                device_name=host.name,\n                interface_name=iface.name,\n                summary=f\"{host.name}: Interface {iface.name} has no IP address configured\",\n                explanation=\"Cannot originate ping because interface has no IPv4 configuration.\",\n                status=\"DROP\"\n            )\n            return self.events\n\n        for seq in range(1, count + 1):\n            icmp = ICMPPacket(type=ICMP_ECHO_REQUEST, sequence=seq, payload=\"NetForge Ping 32 bytes\")\n            ip_pkt = IPv4Packet(src_ip=iface.ip_address, dst_ip=target_ip_str, ttl=64, protocol=\"ICMP\", payload=icmp)\n            self._send_ip_packet_from_host(host, iface, ip_pkt)\n            self.run_all(max_steps=50)\n\n        return self.events\n",
  "labs.py": "\"\"\"\nGuided Networking Labs and Verification Engine for NetForge.\n\nDefines 5 interactive lab scenarios with starting topologies, learning objectives,\ntasks, hints, automated validation rules, and educational conclusions.\n\"\"\"\n\nfrom typing import Dict, List, Any, Optional\nimport copy\nfrom netforge.topology import Topology\nfrom netforge.devices import Host, Switch, Router, Interface\nfrom netforge.links import Link\nfrom netforge.engine import SimulationEngine\nfrom netforge.addressing import is_same_subnet\n\n\ndef build_lab_1_topology() -> Topology:\n    \"\"\"Lab 1: First Network \u2014 2 PCs and 1 Switch.\"\"\"\n    topo = Topology(id=\"lab-1\", name=\"Lab 1: First Network\", description=\"Connect two PCs to a switch and configure IP addressing.\")\n    \n    pc1 = Host(\"pc1\", \"PC1\", \"pc\", x=120, y=200)\n    pc1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:01\"))\n    \n    pc2 = Host(\"pc2\", \"PC2\", \"pc\", x=520, y=200)\n    pc2.add_interface(Interface(\"eth0\", \"00:50:79:66:68:02\"))\n\n    sw1 = Switch(\"sw1\", \"Switch1\", x=320, y=200)\n    for i in range(1, 9):\n        sw1.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:33:55:0{i}\"))\n\n    topo.add_device(pc1)\n    topo.add_device(pc2)\n    topo.add_device(sw1)\n\n    topo.add_link(Link(\"link1\", \"pc1\", \"eth0\", \"sw1\", \"Fa0/1\"))\n    topo.add_link(Link(\"link2\", \"pc2\", \"eth0\", \"sw1\", \"Fa0/2\"))\n\n    return topo\n\n\ndef build_lab_2_topology() -> Topology:\n    \"\"\"Lab 2: Fix the Subnet Mask \u2014 Misconfigured /25 vs /24 mask.\"\"\"\n    topo = Topology(id=\"lab-2\", name=\"Lab 2: Fix the Subnet Mask\", description=\"Diagnose and resolve an addressing subnet mask mismatch.\")\n    \n    pc1 = Host(\"pc1\", \"PC1\", \"pc\", x=140, y=200)\n    pc1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:01\", ip_address=\"192.168.1.50\", subnet_mask=\"255.255.255.0\"))\n    \n    # PC2 has /25 mask (255.255.255.128) with IP 192.168.1.200.\n    # In /25, 192.168.1.200 is in network 192.168.1.128/25, while 192.168.1.50 is in 192.168.1.0/25!\n    pc2 = Host(\"pc2\", \"PC2\", \"pc\", x=500, y=200)\n    pc2.add_interface(Interface(\"eth0\", \"00:50:79:66:68:02\", ip_address=\"192.168.1.200\", subnet_mask=\"255.255.255.128\"))\n\n    sw1 = Switch(\"sw1\", \"Switch1\", x=320, y=200)\n    for i in range(1, 9):\n        sw1.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:33:55:0{i}\"))\n\n    topo.add_device(pc1)\n    topo.add_device(pc2)\n    topo.add_device(sw1)\n\n    topo.add_link(Link(\"link1\", \"pc1\", \"eth0\", \"sw1\", \"Fa0/1\"))\n    topo.add_link(Link(\"link2\", \"pc2\", \"eth0\", \"sw1\", \"Fa0/2\"))\n\n    return topo\n\n\ndef build_lab_3_topology() -> Topology:\n    \"\"\"Lab 3: Route Between Networks \u2014 2 LANs connected by a Router.\"\"\"\n    topo = Topology(id=\"lab-3\", name=\"Lab 3: Route Between Networks\", description=\"Configure router interfaces and default gateways to interconnect two distinct subnets.\")\n    \n    pc1 = Host(\"pc1\", \"PC1\", \"pc\", x=100, y=140)\n    pc1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:01\", ip_address=\"192.168.10.10\", subnet_mask=\"255.255.255.0\"))\n\n    sw1 = Switch(\"sw1\", \"Switch1\", x=240, y=140)\n    for i in range(1, 9):\n        sw1.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:11:11:0{i}\"))\n\n    r1 = Router(\"r1\", \"Router1\", x=400, y=220)\n    r1.add_interface(Interface(\"Gi0/0\", \"00:AA:BB:CC:DD:01\"))\n    r1.add_interface(Interface(\"Gi0/1\", \"00:AA:BB:CC:DD:02\"))\n\n    sw2 = Switch(\"sw2\", \"Switch2\", x=560, y=300)\n    for i in range(1, 9):\n        sw2.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:22:22:0{i}\"))\n\n    pc2 = Host(\"pc2\", \"PC2\", \"pc\", x=700, y=300)\n    pc2.add_interface(Interface(\"eth0\", \"00:50:79:66:68:02\", ip_address=\"192.168.20.20\", subnet_mask=\"255.255.255.0\"))\n\n    topo.add_device(pc1)\n    topo.add_device(sw1)\n    topo.add_device(r1)\n    topo.add_device(sw2)\n    topo.add_device(pc2)\n\n    topo.add_link(Link(\"link1\", \"pc1\", \"eth0\", \"sw1\", \"Fa0/1\"))\n    topo.add_link(Link(\"link2\", \"sw1\", \"Fa0/2\", \"r1\", \"Gi0/0\"))\n    topo.add_link(Link(\"link3\", \"r1\", \"Gi0/1\", \"sw2\", \"Fa0/1\"))\n    topo.add_link(Link(\"link4\", \"sw2\", \"Fa0/2\", \"pc2\", \"eth0\"))\n\n    return topo\n\n\ndef build_lab_4_topology() -> Topology:\n    \"\"\"Lab 4: Troubleshoot Connectivity \u2014 Broken network with 3 deliberate faults.\"\"\"\n    topo = Topology(id=\"lab-4\", name=\"Lab 4: Troubleshoot Connectivity\", description=\"Identify and fix multiple misconfigurations to restore end-to-end communication.\")\n    \n    pc1 = Host(\"pc1\", \"PC1\", \"pc\", x=100, y=160, default_gateway=\"10.0.1.1\")\n    pc1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:01\", ip_address=\"10.0.1.10\", subnet_mask=\"255.255.255.0\"))\n\n    sw1 = Switch(\"sw1\", \"Switch1\", x=240, y=160)\n    for i in range(1, 9):\n        sw1.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:11:33:0{i}\"))\n\n    r1 = Router(\"r1\", \"Router1\", x=400, y=220)\n    # Fault 1: Gi0/0 is administratively shut down!\n    r1.add_interface(Interface(\"Gi0/0\", \"00:AA:BB:CC:11:01\", ip_address=\"10.0.1.1\", subnet_mask=\"255.255.255.0\", admin_up=False))\n    r1.add_interface(Interface(\"Gi0/1\", \"00:AA:BB:CC:11:02\", ip_address=\"10.0.2.1\", subnet_mask=\"255.255.255.0\", admin_up=True))\n\n    sw2 = Switch(\"sw2\", \"Switch2\", x=560, y=280)\n    for i in range(1, 9):\n        sw2.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:22:33:0{i}\"))\n\n    # Fault 2: PC2 has invalid default gateway pointing to 10.0.2.99 instead of 10.0.2.1!\n    pc2 = Host(\"pc2\", \"PC2\", \"pc\", x=700, y=280, default_gateway=\"10.0.2.99\")\n    pc2.add_interface(Interface(\"eth0\", \"00:50:79:66:68:02\", ip_address=\"10.0.2.20\", subnet_mask=\"255.255.255.0\"))\n\n    topo.add_device(pc1)\n    topo.add_device(sw1)\n    topo.add_device(r1)\n    topo.add_device(sw2)\n    topo.add_device(pc2)\n\n    topo.add_link(Link(\"link1\", \"pc1\", \"eth0\", \"sw1\", \"Fa0/1\"))\n    topo.add_link(Link(\"link2\", \"sw1\", \"Fa0/2\", \"r1\", \"Gi0/0\"))\n    topo.add_link(Link(\"link3\", \"r1\", \"Gi0/1\", \"sw2\", \"Fa0/1\"))\n    # Fault 3: Link 4 is administratively disconnected!\n    topo.add_link(Link(\"link4\", \"sw2\", \"Fa0/2\", \"pc2\", \"eth0\", is_up=False))\n\n    return topo\n\n\ndef build_lab_5_topology() -> Topology:\n    \"\"\"Lab 5: Observe ARP and Routing \u2014 Cross-network multi-hop observation.\"\"\"\n    topo = Topology(id=\"lab-5\", name=\"Lab 5: Observe ARP and Routing\", description=\"Observe how ARP operates locally vs across routed boundaries.\")\n    \n    pc1 = Host(\"pc1\", \"PC1\", \"pc\", x=120, y=160, default_gateway=\"172.16.1.1\")\n    pc1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:01\", ip_address=\"172.16.1.10\", subnet_mask=\"255.255.255.0\"))\n\n    sw1 = Switch(\"sw1\", \"Switch1\", x=260, y=160)\n    for i in range(1, 9):\n        sw1.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:55:11:0{i}\"))\n\n    r1 = Router(\"r1\", \"Router1\", x=400, y=220)\n    r1.add_interface(Interface(\"Gi0/0\", \"00:AA:BB:55:11:01\", ip_address=\"172.16.1.1\", subnet_mask=\"255.255.255.0\"))\n    r1.add_interface(Interface(\"Gi0/1\", \"00:AA:BB:55:11:02\", ip_address=\"172.16.2.1\", subnet_mask=\"255.255.255.0\"))\n\n    sw2 = Switch(\"sw2\", \"Switch2\", x=540, y=280)\n    for i in range(1, 9):\n        sw2.add_interface(Interface(f\"Fa0/{i}\", f\"00:01:42:55:22:0{i}\"))\n\n    srv1 = Host(\"srv1\", \"WebServer\", \"server\", x=680, y=280, default_gateway=\"172.16.2.1\")\n    srv1.add_interface(Interface(\"eth0\", \"00:50:79:66:68:99\", ip_address=\"172.16.2.100\", subnet_mask=\"255.255.255.0\"))\n\n    topo.add_device(pc1)\n    topo.add_device(sw1)\n    topo.add_device(r1)\n    topo.add_device(sw2)\n    topo.add_device(srv1)\n\n    topo.add_link(Link(\"link1\", \"pc1\", \"eth0\", \"sw1\", \"Fa0/1\"))\n    topo.add_link(Link(\"link2\", \"sw1\", \"Fa0/2\", \"r1\", \"Gi0/0\"))\n    topo.add_link(Link(\"link3\", \"r1\", \"Gi0/1\", \"sw2\", \"Fa0/1\"))\n    topo.add_link(Link(\"link4\", \"sw2\", \"Fa0/2\", \"srv1\", \"eth0\"))\n\n    return topo\n\n\nLAB_DEFINITIONS: Dict[str, Dict[str, Any]] = {\n    \"lab-1\": {\n        \"id\": \"lab-1\",\n        \"title\": \"Lab 1: First Network\",\n        \"difficulty\": \"Beginner\",\n        \"description\": \"Build foundational networking knowledge by assigning IPv4 addresses to two PCs on a switch and observing ARP and ICMP echo.\",\n        \"objectives\": [\n            \"Configure IPv4 addresses and subnet masks on both PCs within the same subnet (e.g., 192.168.1.10/24 and 192.168.1.20/24).\",\n            \"Verify that interfaces are administratively UP.\",\n            \"Originate a ping from PC1 to PC2.\",\n            \"Observe the initial broadcast ARP Request and unicast ARP Reply, followed by ICMP Echo Request and Reply.\"\n        ],\n        \"tasks\": [\n            {\"id\": \"t1\", \"text\": \"Assign PC1 an IP address (e.g., 192.168.1.10) with subnet mask 255.255.255.0\"},\n            {\"id\": \"t2\", \"text\": \"Assign PC2 an IP address in the same subnet (e.g., 192.168.1.20) with mask 255.255.255.0\"},\n            {\"id\": \"t3\", \"text\": \"Successfully ping PC2 from PC1\"}\n        ],\n        \"hints\": [\n            \"Click on PC1, open its Interface Config, and enter 192.168.1.10 with mask 255.255.255.0.\",\n            \"Click on PC2 and enter 192.168.1.20 with the same mask 255.255.255.0.\",\n            \"Open the CLI on PC1 and type 'ping 192.168.1.20' or click 'Send Ping' in the control dock.\"\n        ],\n        \"concept_summary\": (\n            \"Because both hosts share the same subnet prefix (192.168.1.0/24), no router is required. \"\n            \"PC1 uses ARP to find PC2's MAC address, and Switch1 learns both MAC addresses to forward unicast frames.\"\n        ),\n        \"builder\": build_lab_1_topology\n    },\n    \"lab-2\": {\n        \"id\": \"lab-2\",\n        \"title\": \"Lab 2: Fix the Subnet Mask\",\n        \"difficulty\": \"Beginner\",\n        \"description\": \"Diagnose an addressing mismatch where PC1 and PC2 cannot communicate due to inconsistent subnet masks.\",\n        \"objectives\": [\n            \"Inspect PC1 (192.168.1.50/24) and PC2 (192.168.1.200/25).\",\n            \"Understand why PC2 calculates 192.168.1.50 as belonging to a different subnet.\",\n            \"Correct PC2's subnet mask to 255.255.255.0 (/24).\",\n            \"Verify successful two-way ICMP communication.\"\n        ],\n        \"tasks\": [\n            {\"id\": \"t1\", \"text\": \"Identify the incorrect subnet mask on PC2\"},\n            {\"id\": \"t2\", \"text\": \"Change PC2's subnet mask to 255.255.255.0 (/24)\"},\n            {\"id\": \"t3\", \"text\": \"Verify successful ping from PC1 to 192.168.1.200\"}\n        ],\n        \"hints\": [\n            \"Use the Subnet Calculator panel to inspect 192.168.1.200 with mask 255.255.255.128 (/25). Notice that /25 creates two subnets: .0-.127 and .128-.255.\",\n            \"Since 192.168.1.50 is in the lower range and .200 is in the upper range, PC2 believes PC1 is remote and drops packets without a gateway.\",\n            \"Change PC2's mask to 255.255.255.0.\"\n        ],\n        \"concept_summary\": (\n            \"Subnet masks define the boundary between network bits and host bits. \"\n            \"When masks disagree, one host may consider a destination local while the other considers it remote, causing asymmetric communication failures.\"\n        ),\n        \"builder\": build_lab_2_topology\n    },\n    \"lab-3\": {\n        \"id\": \"lab-3\",\n        \"title\": \"Lab 3: Route Between Networks\",\n        \"difficulty\": \"Intermediate\",\n        \"description\": \"Connect two distinct LANs across a router, configure default gateways, and observe router forwarding.\",\n        \"objectives\": [\n            \"Configure Router1 Gi0/0 with IP 192.168.10.1 and mask 255.255.255.0.\",\n            \"Configure Router1 Gi0/1 with IP 192.168.20.1 and mask 255.255.255.0.\",\n            \"Configure PC1's default gateway as 192.168.10.1.\",\n            \"Configure PC2's default gateway as 192.168.20.1.\",\n            \"Ping from PC1 (192.168.10.10) to PC2 (192.168.20.20).\"\n        ],\n        \"tasks\": [\n            {\"id\": \"t1\", \"text\": \"Configure Router1 Gi0/0 IP to 192.168.10.1 /24 and enable interface\"},\n            {\"id\": \"t2\", \"text\": \"Configure Router1 Gi0/1 IP to 192.168.20.1 /24 and enable interface\"},\n            {\"id\": \"t3\", \"text\": \"Set PC1 default gateway to 192.168.10.1\"},\n            {\"id\": \"t4\", \"text\": \"Set PC2 default gateway to 192.168.20.1\"},\n            {\"id\": \"t5\", \"text\": \"Successfully ping PC2 (192.168.20.20) from PC1\"}\n        ],\n        \"hints\": [\n            \"On Router1 CLI: 'int Gi0/0' -> 'ip address 192.168.10.1 255.255.255.0' -> 'no shutdown'.\",\n            \"Do the same for Gi0/1 with 192.168.20.1 255.255.255.0.\",\n            \"Set PC1 default gateway to 192.168.10.1 and PC2 default gateway to 192.168.20.1.\",\n            \"Type 'ping 192.168.20.20' on PC1.\"\n        ],\n        \"concept_summary\": (\n            \"Routers connect disparate broadcast domains. When PC1 sends traffic to 192.168.20.20, \"\n            \"it recognizes that the destination is outside its local subnet and ARPs for its default gateway. \"\n            \"The router receives the frame, decrements TTL, looks up the route, and forwards the packet out Gi0/1.\"\n        ),\n        \"builder\": build_lab_3_topology\n    },\n    \"lab-4\": {\n        \"id\": \"lab-4\",\n        \"title\": \"Lab 4: Troubleshoot Connectivity\",\n        \"difficulty\": \"Intermediate\",\n        \"description\": \"A production network is failing. Use diagnostic CLI commands to uncover 3 deliberate faults and restore connectivity.\",\n        \"objectives\": [\n            \"Use 'show interfaces' on Router1 to find an administratively disabled port.\",\n            \"Use 'no shutdown' to bring Router1 Gi0/0 UP.\",\n            \"Inspect PC2 configuration to find the incorrect default gateway (10.0.2.99).\",\n            \"Correct PC2 default gateway to 10.0.2.1.\",\n            \"Inspect the physical links to identify the disconnected cable on PC2 and enable it.\",\n            \"Verify restored ping between PC1 and PC2.\"\n        ],\n        \"tasks\": [\n            {\"id\": \"t1\", \"text\": \"Enable Router1 Gi0/0 (currently shutdown)\"},\n            {\"id\": \"t2\", \"text\": \"Fix PC2 default gateway (change 10.0.2.99 to 10.0.2.1)\"},\n            {\"id\": \"t3\", \"text\": \"Reconnect the virtual link between Switch2 and PC2\"},\n            {\"id\": \"t4\", \"text\": \"Achieve 100% ping success from PC1 to PC2\"}\n        ],\n        \"hints\": [\n            \"Check Router1 interfaces using 'show ip int brief'. Notice that Gi0/0 is administratively down.\",\n            \"Click on PC2 and check its default gateway. The router interface on that subnet is 10.0.2.1, but PC2 was set to 10.0.2.99.\",\n            \"Select the link between Switch2 and PC2 and toggle it UP.\",\n            \"Test with 'ping 10.0.2.20' from PC1.\"\n        ],\n        \"concept_summary\": (\n            \"Systematic network troubleshooting requires checking Layer 1 (cable/link status), \"\n            \"Layer 2 (interface administrative state and MAC learning), and Layer 3 (IP configuration and gateways).\"\n        ),\n        \"builder\": build_lab_4_topology\n    },\n    \"lab-5\": {\n        \"id\": \"lab-5\",\n        \"title\": \"Lab 5: Observe ARP and Routing\",\n        \"difficulty\": \"Advanced\",\n        \"description\": \"Deeply observe how Address Resolution Protocol operates differently when accessing local hosts versus remote destinations across a router.\",\n        \"objectives\": [\n            \"Inspect the ARP tables on PC1, Router1, and WebServer prior to sending traffic.\",\n            \"Send an ICMP ping from PC1 (172.16.1.10) to WebServer (172.16.2.100).\",\n            \"Observe that PC1 broadcasts an ARP Request for Router1 (172.16.1.1), NOT for WebServer.\",\n            \"Observe Router1 receiving the packet, checking its routing table, and broadcasting an ARP Request for WebServer (172.16.2.100).\",\n            \"Inspect the populated ARP tables and verify MAC resolution differences.\"\n        ],\n        \"tasks\": [\n            {\"id\": \"t1\", \"text\": \"Verify initial empty ARP tables using 'show arp' on PC1 and Router1\"},\n            {\"id\": \"t2\", \"text\": \"Ping WebServer (172.16.2.100) from PC1\"},\n            {\"id\": \"t3\", \"text\": \"Verify PC1 ARP table contains Router1's MAC address, not WebServer's MAC\"}\n        ],\n        \"hints\": [\n            \"On PC1, type 'show arp' to see that the ARP cache is empty.\",\n            \"Run 'ping 172.16.2.100' on PC1.\",\n            \"Inspect the simulation event trace step-by-step. Notice that PC1 never ARPs for 172.16.2.100 because it is outside PC1's subnet.\"\n        ],\n        \"concept_summary\": (\n            \"A host only ARPs for IP addresses located on its own local subnet. \"\n            \"For all remote traffic, the host ARPs for its next-hop default gateway. \"\n            \"The router decapsulates the Layer 2 frame and re-encapsulates it with a new source and destination MAC on each hop!\"\n        ),\n        \"builder\": build_lab_5_topology\n    }\n}\n\n\ndef evaluate_lab(lab_id: str, topology: Topology) -> Dict[str, Any]:\n    \"\"\"\n    Validate the current state of a topology against lab criteria.\n    Returns task status, overall completion boolean, and feedback.\n    \"\"\"\n    if lab_id not in LAB_DEFINITIONS:\n        return {\"completed\": False, \"tasks\": [], \"message\": f\"Unknown lab ID: {lab_id}\"}\n\n    lab_info = LAB_DEFINITIONS[lab_id]\n    tasks = copy.deepcopy(lab_info[\"tasks\"])\n\n    if lab_id == \"lab-1\":\n        pc1 = topology.devices.get(\"pc1\")\n        pc2 = topology.devices.get(\"pc2\")\n        sw1 = topology.devices.get(\"sw1\")\n\n        if1 = pc1.get_interface(\"eth0\") if pc1 else None\n        if2 = pc2.get_interface(\"eth0\") if pc2 else None\n\n        # Task 1: PC1 IP & mask configured\n        t1_done = bool(if1 and if1.ip_address and if1.subnet_mask and if1.admin_up)\n        # Task 2: PC2 IP in same subnet\n        t2_done = bool(\n            if1 and if2 and if1.ip_address and if2.ip_address and\n            if1.subnet_mask and if2.subnet_mask and\n            if1.ip_address != if2.ip_address and\n            is_same_subnet(if1.ip_address, if2.ip_address, if1.subnet_mask)\n        )\n        # Task 3: Ping succeeds\n        t3_done = False\n        if t1_done and t2_done:\n            eng = SimulationEngine(topology)\n            evs = eng.ping(\"pc1\", if2.ip_address, count=1)\n            t3_done = any(e.event_type == \"PING_SUCCESS\" for e in evs)\n\n        tasks[0][\"completed\"] = t1_done\n        tasks[1][\"completed\"] = t2_done\n        tasks[2][\"completed\"] = t3_done\n\n    elif lab_id == \"lab-2\":\n        pc1 = topology.devices.get(\"pc1\")\n        pc2 = topology.devices.get(\"pc2\")\n        if1 = pc1.get_interface(\"eth0\") if pc1 else None\n        if2 = pc2.get_interface(\"eth0\") if pc2 else None\n\n        t1_done = True\n        t2_done = bool(if2 and if2.subnet_mask in (\"255.255.255.0\", \"/24\"))\n        t3_done = False\n        if t2_done and if1 and if2:\n            eng = SimulationEngine(topology)\n            evs = eng.ping(\"pc1\", if2.ip_address, count=1)\n            t3_done = any(e.event_type == \"PING_SUCCESS\" for e in evs)\n\n        tasks[0][\"completed\"] = t1_done\n        tasks[1][\"completed\"] = t2_done\n        tasks[2][\"completed\"] = t3_done\n\n    elif lab_id == \"lab-3\":\n        r1 = topology.devices.get(\"r1\")\n        pc1 = topology.devices.get(\"pc1\")\n        pc2 = topology.devices.get(\"pc2\")\n\n        r_gi0 = r1.get_interface(\"Gi0/0\") if r1 else None\n        r_gi1 = r1.get_interface(\"Gi0/1\") if r1 else None\n        pc1_if = pc1.get_interface(\"eth0\") if pc1 else None\n        pc2_if = pc2.get_interface(\"eth0\") if pc2 else None\n\n        t1_done = bool(r_gi0 and r_gi0.admin_up and r_gi0.ip_address == \"192.168.10.1\")\n        t2_done = bool(r_gi1 and r_gi1.admin_up and r_gi1.ip_address == \"192.168.20.1\")\n        t3_done = bool(isinstance(pc1, Host) and pc1.default_gateway == \"192.168.10.1\")\n        t4_done = bool(isinstance(pc2, Host) and pc2.default_gateway == \"192.168.20.1\")\n\n        t5_done = False\n        if t1_done and t2_done and t3_done and t4_done and pc2_if:\n            eng = SimulationEngine(topology)\n            evs = eng.ping(\"pc1\", pc2_if.ip_address, count=1)\n            t5_done = any(e.event_type == \"PING_SUCCESS\" for e in evs)\n\n        tasks[0][\"completed\"] = t1_done\n        tasks[1][\"completed\"] = t2_done\n        tasks[2][\"completed\"] = t3_done\n        tasks[3][\"completed\"] = t4_done\n        tasks[4][\"completed\"] = t5_done\n\n    elif lab_id == \"lab-4\":\n        r1 = topology.devices.get(\"r1\")\n        pc2 = topology.devices.get(\"pc2\")\n        link4 = topology.links.get(\"link4\")\n\n        r_gi0 = r1.get_interface(\"Gi0/0\") if r1 else None\n\n        t1_done = bool(r_gi0 and r_gi0.admin_up)\n        t2_done = bool(isinstance(pc2, Host) and pc2.default_gateway == \"10.0.2.1\")\n        t3_done = bool(link4 and link4.is_up)\n\n        t4_done = False\n        if t1_done and t2_done and t3_done and pc2:\n            eng = SimulationEngine(topology)\n            evs = eng.ping(\"pc1\", \"10.0.2.20\", count=1)\n            t4_done = any(e.event_type == \"PING_SUCCESS\" for e in evs)\n\n        tasks[0][\"completed\"] = t1_done\n        tasks[1][\"completed\"] = t2_done\n        tasks[2][\"completed\"] = t3_done\n        tasks[3][\"completed\"] = t4_done\n\n    elif lab_id == \"lab-5\":\n        pc1 = topology.devices.get(\"pc1\")\n        srv1 = topology.devices.get(\"srv1\")\n        r1 = topology.devices.get(\"r1\")\n\n        t1_done = True\n        t2_done = False\n        t3_done = False\n\n        if pc1 and srv1 and r1:\n            eng = SimulationEngine(topology)\n            evs = eng.ping(\"pc1\", \"172.16.2.100\", count=1)\n            t2_done = any(e.event_type == \"PING_SUCCESS\" for e in evs)\n            \n            # Check PC1 ARP table contains Router1 IP (172.16.1.1)\n            t3_done = \"172.16.1.1\" in pc1.arp_cache and \"172.16.2.100\" not in pc1.arp_cache\n\n        tasks[0][\"completed\"] = t1_done\n        tasks[1][\"completed\"] = t2_done\n        tasks[2][\"completed\"] = t3_done\n\n    all_done = all(t.get(\"completed\", False) for t in tasks)\n\n    return {\n        \"lab_id\": lab_id,\n        \"title\": lab_info[\"title\"],\n        \"completed\": all_done,\n        \"tasks\": tasks,\n        \"concept_summary\": lab_info[\"concept_summary\"] if all_done else None,\n        \"message\": \"Congratulations! You have completed all lab tasks!\" if all_done else \"Work in progress. Complete all tasks to pass the lab.\"\n    }\n",
  "links.py": "\"\"\"\nVirtual Link Model for NetForge.\n\nRepresents Ethernet links connecting interface endpoints between devices,\nwith administrative state, latency, and operational checks.\n\"\"\"\n\nfrom typing import Dict, Any, Tuple, Optional\n\n\nclass Link:\n    def __init__(\n        self,\n        id: str,\n        device_a_id: str,\n        interface_a_name: str,\n        device_b_id: str,\n        interface_b_name: str,\n        is_up: bool = True,\n        bandwidth_mbps: int = 1000,\n        delay_ms: float = 1.0\n    ):\n        self.id = id\n        self.device_a_id = device_a_id\n        self.interface_a_name = interface_a_name\n        self.device_b_id = device_b_id\n        self.interface_b_name = interface_b_name\n        self.is_up = is_up\n        self.bandwidth_mbps = bandwidth_mbps\n        self.delay_ms = delay_ms\n\n    def connects_device(self, device_id: str) -> bool:\n        return self.device_a_id == device_id or self.device_b_id == device_id\n\n    def connects_interface(self, device_id: str, iface_name: str) -> bool:\n        return (\n            (self.device_a_id == device_id and self.interface_a_name == iface_name) or\n            (self.device_b_id == device_id and self.interface_b_name == iface_name)\n        )\n\n    def get_other_endpoint(self, device_id: str, iface_name: str) -> Optional[Tuple[str, str]]:\n        if self.device_a_id == device_id and self.interface_a_name == iface_name:\n            return (self.device_b_id, self.interface_b_name)\n        elif self.device_b_id == device_id and self.interface_b_name == iface_name:\n            return (self.device_a_id, self.interface_a_name)\n        return None\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"id\": self.id,\n            \"device_a_id\": self.device_a_id,\n            \"interface_a_name\": self.interface_a_name,\n            \"device_b_id\": self.device_b_id,\n            \"interface_b_name\": self.interface_b_name,\n            \"is_up\": self.is_up,\n            \"bandwidth_mbps\": self.bandwidth_mbps,\n            \"delay_ms\": self.delay_ms,\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Link\":\n        return cls(\n            id=data[\"id\"],\n            device_a_id=data[\"device_a_id\"],\n            interface_a_name=data[\"interface_a_name\"],\n            device_b_id=data[\"device_b_id\"],\n            interface_b_name=data[\"interface_b_name\"],\n            is_up=data.get(\"is_up\", True),\n            bandwidth_mbps=data.get(\"bandwidth_mbps\", 1000),\n            delay_ms=data.get(\"delay_ms\", 1.0)\n        )\n",
  "protocols.py": "\"\"\"\nNetworking Protocol Data Models for NetForge.\n\nDefines Layer 2 (Ethernet), Layer 3 (ARP, IPv4), and Layer 4 (ICMP)\npackets, frames, headers, and protocol serialization.\n\"\"\"\n\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Optional, Union, Dict, Any\n\n\nBROADCAST_MAC = \"FF:FF:FF:FF:FF:FF\"\nZERO_MAC = \"00:00:00:00:00:00\"\n\nETHERTYPE_IPV4 = \"IPv4\"     # 0x0800\nETHERTYPE_ARP = \"ARP\"       # 0x0806\n\nARP_OP_REQUEST = \"REQUEST\"  # Opcode 1\nARP_OP_REPLY = \"REPLY\"      # Opcode 2\n\nIP_PROTO_ICMP = \"ICMP\"      # Protocol 1\nIP_PROTO_TCP = \"TCP\"        # Protocol 6\nIP_PROTO_UDP = \"UDP\"        # Protocol 17\n\nICMP_ECHO_REPLY = \"ECHO_REPLY\"                      # Type 0\nICMP_DEST_UNREACHABLE = \"DESTINATION_UNREACHABLE\"  # Type 3\nICMP_ECHO_REQUEST = \"ECHO_REQUEST\"                  # Type 8\nICMP_TIME_EXCEEDED = \"TIME_EXCEEDED\"                # Type 11\n\n# ICMP Codes\nICMP_CODE_NET_UNREACHABLE = 0\nICMP_CODE_HOST_UNREACHABLE = 1\nICMP_CODE_PORT_UNREACHABLE = 3\nICMP_CODE_TTL_EXPIRED = 0\n\n\n@dataclass\nclass ICMPPacket:\n    type: str  # ECHO_REQUEST, ECHO_REPLY, TIME_EXCEEDED, DESTINATION_UNREACHABLE\n    code: int = 0\n    sequence: int = 1\n    identifier: int = 100\n    payload: str = \"NetForge ping payload (32 bytes)\"\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"layer\": \"Layer 4 (ICMP)\",\n            \"type\": self.type,\n            \"code\": self.code,\n            \"sequence\": self.sequence,\n            \"identifier\": self.identifier,\n            \"payload\": self.payload,\n            \"type_number\": 8 if self.type == ICMP_ECHO_REQUEST else (0 if self.type == ICMP_ECHO_REPLY else (11 if self.type == ICMP_TIME_EXCEEDED else 3))\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"ICMPPacket\":\n        return cls(\n            type=data.get(\"type\", ICMP_ECHO_REQUEST),\n            code=data.get(\"code\", 0),\n            sequence=data.get(\"sequence\", 1),\n            identifier=data.get(\"identifier\", 100),\n            payload=data.get(\"payload\", \"\")\n        )\n\n\n@dataclass\nclass ARPPacket:\n    operation: str  # REQUEST or REPLY\n    sender_mac: str\n    sender_ip: str\n    target_mac: str\n    target_ip: str\n    hardware_type: str = \"Ethernet (1)\"\n    protocol_type: str = \"IPv4 (0x0800)\"\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"layer\": \"Layer 3 (ARP)\",\n            \"operation\": self.operation,\n            \"opcode\": 1 if self.operation == ARP_OP_REQUEST else 2,\n            \"sender_mac\": self.sender_mac,\n            \"sender_ip\": self.sender_ip,\n            \"target_mac\": self.target_mac,\n            \"target_ip\": self.target_ip,\n            \"hardware_type\": self.hardware_type,\n            \"protocol_type\": self.protocol_type,\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"ARPPacket\":\n        return cls(\n            operation=data.get(\"operation\", ARP_OP_REQUEST),\n            sender_mac=data.get(\"sender_mac\", ZERO_MAC),\n            sender_ip=data.get(\"sender_ip\", \"0.0.0.0\"),\n            target_mac=data.get(\"target_mac\", ZERO_MAC),\n            target_ip=data.get(\"target_ip\", \"0.0.0.0\"),\n            hardware_type=data.get(\"hardware_type\", \"Ethernet (1)\"),\n            protocol_type=data.get(\"protocol_type\", \"IPv4 (0x0800)\"),\n        )\n\n\n@dataclass\nclass IPv4Packet:\n    src_ip: str\n    dst_ip: str\n    ttl: int = 64\n    protocol: str = IP_PROTO_ICMP\n    identification: int = 54321\n    flags: str = \"DF (Don't Fragment)\"\n    payload: Union[ICMPPacket, Dict[str, Any]] = field(default_factory=dict)\n    header_checksum: str = \"0x7a31 (verified)\"\n\n    def to_dict(self) -> Dict[str, Any]:\n        payload_dict = self.payload.to_dict() if hasattr(self.payload, \"to_dict\") else self.payload\n        return {\n            \"layer\": \"Layer 3 (IPv4)\",\n            \"src_ip\": self.src_ip,\n            \"dst_ip\": self.dst_ip,\n            \"ttl\": self.ttl,\n            \"protocol\": self.protocol,\n            \"identification\": self.identification,\n            \"flags\": self.flags,\n            \"header_checksum\": self.header_checksum,\n            \"payload\": payload_dict,\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"IPv4Packet\":\n        raw_payload = data.get(\"payload\", {})\n        if isinstance(raw_payload, dict) and \"type\" in raw_payload:\n            payload = ICMPPacket.from_dict(raw_payload)\n        else:\n            payload = raw_payload\n        return cls(\n            src_ip=data.get(\"src_ip\", \"0.0.0.0\"),\n            dst_ip=data.get(\"dst_ip\", \"0.0.0.0\"),\n            ttl=data.get(\"ttl\", 64),\n            protocol=data.get(\"protocol\", IP_PROTO_ICMP),\n            identification=data.get(\"identification\", 1),\n            flags=data.get(\"flags\", \"DF\"),\n            payload=payload,\n            header_checksum=data.get(\"header_checksum\", \"0x0000\"),\n        )\n\n\n@dataclass\nclass EthernetFrame:\n    src_mac: str\n    dst_mac: str\n    ethertype: str  # ETHERTYPE_IPV4 or ETHERTYPE_ARP\n    payload: Union[ARPPacket, IPv4Packet, Dict[str, Any]]\n    fcs: str = \"0x4b7c128f (CRC valid)\"\n\n    def is_broadcast(self) -> bool:\n        return self.dst_mac.upper() == BROADCAST_MAC\n\n    def to_dict(self) -> Dict[str, Any]:\n        payload_dict = self.payload.to_dict() if hasattr(self.payload, \"to_dict\") else self.payload\n        return {\n            \"layer\": \"Layer 2 (Ethernet)\",\n            \"src_mac\": self.src_mac,\n            \"dst_mac\": self.dst_mac,\n            \"ethertype\": self.ethertype,\n            \"is_broadcast\": self.is_broadcast(),\n            \"fcs\": self.fcs,\n            \"payload\": payload_dict,\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"EthernetFrame\":\n        ethertype = data.get(\"ethertype\", ETHERTYPE_IPV4)\n        raw_payload = data.get(\"payload\", {})\n        if ethertype == ETHERTYPE_ARP:\n            payload = ARPPacket.from_dict(raw_payload) if isinstance(raw_payload, dict) else raw_payload\n        else:\n            payload = IPv4Packet.from_dict(raw_payload) if isinstance(raw_payload, dict) else raw_payload\n\n        return cls(\n            src_mac=data.get(\"src_mac\", ZERO_MAC),\n            dst_mac=data.get(\"dst_mac\", BROADCAST_MAC),\n            ethertype=ethertype,\n            payload=payload,\n            fcs=data.get(\"fcs\", \"0x00000000\"),\n        )\n",
  "topology.py": "\"\"\"\nTopology Model and Schema Validation for NetForge.\n\nManages the network graph, device inventory, virtual links,\nand validates configuration consistency and schema versioning.\n\"\"\"\n\nfrom typing import Dict, List, Optional, Any, Union, Tuple\nimport uuid\nfrom netforge.addressing import (\n    is_valid_ipv4, is_valid_subnet_mask, mask_str_to_prefix,\n    is_same_subnet, ip_to_int\n)\nfrom netforge.devices import Device, Host, Switch, Router, Hub, Interface\nfrom netforge.links import Link\n\nTOPOLOGY_SCHEMA_VERSION = \"1.0.0\"\nTuple_DevIface = Tuple[Device, Interface]\n\n\nclass Topology:\n    def __init__(\n        self,\n        id: Optional[str] = None,\n        name: str = \"NetForge Lab Topology\",\n        description: str = \"Interactive network simulation topology\",\n        version: str = TOPOLOGY_SCHEMA_VERSION\n    ):\n        self.id = id or str(uuid.uuid4())\n        self.name = name\n        self.description = description\n        self.version = version\n        self.devices: Dict[str, Device] = {}\n        self.links: Dict[str, Link] = {}\n\n    def add_device(self, device: Device):\n        self.devices[device.id] = device\n\n    def remove_device(self, device_id: str):\n        if device_id in self.devices:\n            # First remove all links attached to this device\n            attached_links = [\n                lid for lid, link in self.links.items()\n                if link.connects_device(device_id)\n            ]\n            for lid in attached_links:\n                self.remove_link(lid)\n            del self.devices[device_id]\n\n    def add_link(self, link: Link):\n        # Validate that endpoints exist\n        dev_a = self.devices.get(link.device_a_id)\n        dev_b = self.devices.get(link.device_b_id)\n        if not dev_a or not dev_b:\n            raise ValueError(\"Both devices must exist in topology before creating a link\")\n        \n        iface_a = dev_a.get_interface(link.interface_a_name)\n        iface_b = dev_b.get_interface(link.interface_b_name)\n        if not iface_a or not iface_b:\n            raise ValueError(\"Interfaces must exist on devices before creating a link\")\n\n        # Disconnect any prior links on these interfaces\n        if iface_a.link_id and iface_a.link_id in self.links:\n            self.remove_link(iface_a.link_id)\n        if iface_b.link_id and iface_b.link_id in self.links:\n            self.remove_link(iface_b.link_id)\n\n        iface_a.link_id = link.id\n        iface_b.link_id = link.id\n        self.links[link.id] = link\n\n    def remove_link(self, link_id: str):\n        link = self.links.get(link_id)\n        if link:\n            dev_a = self.devices.get(link.device_a_id)\n            if dev_a:\n                iface_a = dev_a.get_interface(link.interface_a_name)\n                if iface_a and iface_a.link_id == link_id:\n                    iface_a.link_id = None\n\n            dev_b = self.devices.get(link.device_b_id)\n            if dev_b:\n                iface_b = dev_b.get_interface(link.interface_b_name)\n                if iface_b and iface_b.link_id == link_id:\n                    iface_b.link_id = None\n\n            del self.links[link_id]\n\n    def get_link_by_interface(self, device_id: str, iface_name: str) -> Optional[Link]:\n        for link in self.links.values():\n            if link.connects_interface(device_id, iface_name):\n                return link\n        return None\n\n    def get_device_by_ip(self, ip_str: str) -> Optional[Tuple_DevIface]:\n        for dev in self.devices.values():\n            for iface in dev.interfaces.values():\n                if iface.ip_address == ip_str:\n                    return dev, iface\n        return None\n\n    def get_device_by_mac(self, mac_str: str) -> Optional[Tuple_DevIface]:\n        mac_clean = mac_str.upper()\n        for dev in self.devices.values():\n            for iface in dev.interfaces.values():\n                if iface.mac_address == mac_clean:\n                    return dev, iface\n        return None\n\n    def validate(self) -> Dict[str, Any]:\n        \"\"\"\n        Validate topology consistency, detecting address collisions,\n        unreachable gateways, dangling links, and malformed subnet masks.\n        \"\"\"\n        errors = []\n        warnings = []\n\n        configured_ips: Dict[str, List[str]] = {}\n\n        for dev_id, dev in self.devices.items():\n            for if_name, iface in dev.interfaces.items():\n                if iface.ip_address:\n                    if not is_valid_ipv4(iface.ip_address):\n                        errors.append(f\"Device {dev.name} interface {if_name} has invalid IPv4: {iface.ip_address}\")\n                    else:\n                        configured_ips.setdefault(iface.ip_address, []).append(f\"{dev.name}:{if_name}\")\n\n                if iface.subnet_mask and not is_valid_subnet_mask(iface.subnet_mask):\n                    errors.append(f\"Device {dev.name} interface {if_name} has invalid subnet mask: {iface.subnet_mask}\")\n\n                if iface.link_id and iface.link_id not in self.links:\n                    errors.append(f\"Device {dev.name} interface {if_name} references missing link {iface.link_id}\")\n\n            if isinstance(dev, Host) and dev.default_gateway:\n                if not is_valid_ipv4(dev.default_gateway):\n                    errors.append(f\"Device {dev.name} has invalid default gateway IP: {dev.default_gateway}\")\n                else:\n                    # Check if default gateway is in the same subnet as host interface\n                    op_iface = dev.get_first_operational_interface()\n                    if op_iface and op_iface.ip_address and op_iface.subnet_mask:\n                        if not is_same_subnet(op_iface.ip_address, dev.default_gateway, op_iface.subnet_mask):\n                            warnings.append(\n                                f\"Device {dev.name} default gateway {dev.default_gateway} is outside local subnet \"\n                                f\"({op_iface.ip_address}/{op_iface.subnet_mask})\"\n                            )\n\n        # Detect IP Address Collisions\n        for ip, locations in configured_ips.items():\n            if len(locations) > 1:\n                errors.append(f\"Duplicate IPv4 address conflict detected: {ip} is configured on multiple interfaces: {', '.join(locations)}\")\n\n        # Validate Link Endpoints\n        for link_id, link in self.links.items():\n            dev_a = self.devices.get(link.device_a_id)\n            dev_b = self.devices.get(link.device_b_id)\n            if not dev_a or not dev_b:\n                errors.append(f\"Link {link_id} references non-existent device: {link.device_a_id} or {link.device_b_id}\")\n                continue\n            if not dev_a.get_interface(link.interface_a_name):\n                errors.append(f\"Link {link_id} endpoint {dev_a.name} lacks interface {link.interface_a_name}\")\n            if not dev_b.get_interface(link.interface_b_name):\n                errors.append(f\"Link {link_id} endpoint {dev_b.name} lacks interface {link.interface_b_name}\")\n\n        return {\n            \"valid\": len(errors) == 0,\n            \"errors\": errors,\n            \"warnings\": warnings,\n            \"device_count\": len(self.devices),\n            \"link_count\": len(self.links)\n        }\n\n    def to_dict(self) -> Dict[str, Any]:\n        return {\n            \"schema_version\": self.version,\n            \"id\": self.id,\n            \"name\": self.name,\n            \"description\": self.description,\n            \"devices\": [dev.to_dict() for dev in self.devices.values()],\n            \"links\": [link.to_dict() for link in self.links.values()]\n        }\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> \"Topology\":\n        if \"devices\" not in data or \"links\" not in data:\n            raise ValueError(\"Malformed topology JSON: missing 'devices' or 'links' keys\")\n\n        topo = cls(\n            id=data.get(\"id\"),\n            name=data.get(\"name\", \"Imported Topology\"),\n            description=data.get(\"description\", \"\"),\n            version=data.get(\"schema_version\", TOPOLOGY_SCHEMA_VERSION)\n        )\n\n        for dev_data in data[\"devices\"]:\n            dtype = dev_data.get(\"device_type\", \"pc\")\n            if dtype in (\"pc\", \"laptop\", \"server\"):\n                dev = Host.from_dict(dev_data)\n            elif dtype == \"switch\":\n                dev = Switch.from_dict(dev_data)\n            elif dtype == \"router\":\n                dev = Router.from_dict(dev_data)\n            elif dtype == \"hub\":\n                dev = Hub.from_dict(dev_data)\n            else:\n                dev = Host.from_dict(dev_data)\n            topo.add_device(dev)\n\n        for link_data in data[\"links\"]:\n            link = Link.from_dict(link_data)\n            topo.add_link(link)\n\n        return topo\n\n\nTuple_DevIface = tuple[Device, Interface]\n",
  "__init__.py": "\"\"\"\nNetForge \u2014 Interactive Network Simulation Engine.\n\"\"\"\n\n__version__ = \"1.0.0\"\n\nfrom netforge.addressing import (\n    ip_to_int, int_to_ip, mask_str_to_prefix, prefix_to_mask_str,\n    calculate_subnet_info, is_same_subnet, is_valid_ipv4, is_valid_subnet_mask\n)\nfrom netforge.protocols import (\n    EthernetFrame, ARPPacket, IPv4Packet, ICMPPacket,\n    BROADCAST_MAC, ZERO_MAC\n)\nfrom netforge.devices import Host, Switch, Router, Hub, Interface, Route\nfrom netforge.links import Link\nfrom netforge.topology import Topology\nfrom netforge.engine import SimulationEngine, SimulationEvent\nfrom netforge.cli import DeviceCLI\nfrom netforge.labs import LAB_DEFINITIONS, evaluate_lab\n",
  "__main__.py": "\"\"\"\nNetForge CLI interactive session entrypoint.\nAllows running NetForge directly from terminal: python -m netforge\n\"\"\"\n\nimport sys\nfrom netforge.topology import Topology\nfrom netforge.cli import DeviceCLI\nfrom netforge.engine import SimulationEngine\nfrom netforge.labs import build_lab_1_topology, build_lab_3_topology, LAB_DEFINITIONS\n\n\ndef main():\n    print(\"=\" * 60)\n    print(\"  NetForge \u2014 Interactive Educational Network Simulator\")\n    print(\"  Version 1.0.0 (Python Simulation Engine)\")\n    print(\"=\" * 60)\n    print(\"\\nSelect starting lab topology:\")\n    print(\"  1) Lab 1: First Network (Two PCs on a Switch)\")\n    print(\"  2) Lab 3: Route Between Networks (Two LANs + Router)\")\n    print(\"  3) Empty Topology\")\n    print(\"  q) Quit\\n\")\n\n    choice = input(\"Enter choice [1-3, q]: \").strip()\n    if choice == \"1\":\n        topo = build_lab_1_topology()\n    elif choice == \"2\":\n        topo = build_lab_3_topology()\n    elif choice == \"3\":\n        topo = Topology(name=\"Custom Network\")\n    else:\n        print(\"Exiting NetForge.\")\n        sys.exit(0)\n\n    engine = SimulationEngine(topo)\n    active_dev_id = list(topo.devices.keys())[0] if topo.devices else None\n\n    print(f\"\\nLoaded topology: {topo.name}\")\n    print(f\"Devices in network: {', '.join(d.name for d in topo.devices.values())}\")\n    if active_dev_id:\n        print(f\"Currently connected console: {topo.devices[active_dev_id].name}\")\n    print(\"Type 'help' for command list, 'switch <device_name>' to change console, or 'exit' to quit.\\n\")\n\n    while True:\n        if not active_dev_id or active_dev_id not in topo.devices:\n            print(\"No active device console. Use 'switch <name>' to connect to a device.\")\n            cmd_line = input(\"NetForge> \").strip()\n        else:\n            cli = DeviceCLI(topo, active_dev_id)\n            prompt = cli.get_prompt()\n            try:\n                cmd_line = input(prompt).strip()\n            except (EOFError, KeyboardInterrupt):\n                print(\"\\nExiting.\")\n                break\n\n        if not cmd_line:\n            continue\n\n        if cmd_line.lower() in (\"exit\", \"quit\"):\n            print(\"Exiting NetForge session.\")\n            break\n\n        if cmd_line.lower().startswith(\"switch \"):\n            target_name = cmd_line.split()[1].lower()\n            found = None\n            for dev in topo.devices.values():\n                if dev.name.lower() == target_name:\n                    found = dev.id\n                    break\n            if found:\n                active_dev_id = found\n                print(f\"Connected to console of {topo.devices[found].name}\")\n            else:\n                print(f\"% Device '{target_name}' not found in topology.\")\n            continue\n\n        res = cli.execute(cmd_line, engine=engine)\n        if res[\"output\"] == \"__CLEAR__\":\n            print(\"\\033[H\\033[J\", end=\"\")\n        elif res[\"output\"]:\n            print(res[\"output\"])\n\n\nif __name__ == \"__main__\":\n    main()\n"
};
